// ---------------------------------------------------------------- version + changelog
const APP_VERSION = '0.99.57';
const CHANGELOG = [
  { v: '0.99.57', title: 'No more flicker on the desk', notes: ['Library: hovering the cards laid out on the desk no longer flickers. A hovered card used to lift up a little; near its bottom edge, the lift moved it out from under the pointer and back, over and over. It now just gets a gold outline.', 'The open book only changes to a new card once its picture is ready, so the page never flashes empty between cards.'] },
  { v: '0.99.56', title: 'One stack window', notes: ['The stack has one window now, a tidy panel docked at the top right of the table (next to your library). It no longer sits in the middle of the table, no longer darkens the screen, and on phones the extra floating "The Stack" window is gone.', 'Each object on the stack is one row: a slice of its art, its name, what it is (your spell, an opponent\'s spell, a triggered or activated ability) and its targets or chosen modes. The top one is marked NEXT. Your buttons (Pass priority, Copy, Countered, Resolve top) sit together at the bottom.', 'Fold the window to a single line with the arrow (or by clicking its title bar). The folded bar keeps the main button, so you can resolve without unfolding it.', 'The same window shows a spell or ability being resolved (Finish) and cards to choose from your hand.', 'The Stack box in the right column now just says what is on the stack and keeps the tools for adding your opponent\'s spells. The topbar stack button unfolds the window.'] },
  { v: '0.99.55', title: 'Upright on phones', notes: ['Phones (and small tablets) held upright now get their own layout instead of a "turn sideways" screen. The table is one column: deck, graveyard and exile along the top, then creatures, other permanents and lands, with your hand at the bottom. The top bar scrolls sideways.', 'Upright, the stack and the game log open from the "Stack & log" button in the top bar, and tapping a card shows its preview over the table for a moment (tap the preview to close it).', 'The Library upright: three shelves above the open book, which is drawn large across the desk so its pages can be read, and the deck\'s piles below it. A book taken down goes into the open book.', 'Turning the phone sideways switches back to the full table and the wide Library.'] },
  { v: '0.99.54', title: 'Phones and tablets', notes: ['The app now runs in the browser on phones and tablets (iPhone, iPad, Android) and can be installed to the home screen like an app. It keeps working offline once loaded. Address: snipeuoutjsl-netizen.github.io/MTG-Playtester', 'Touch: drag a card with your finger to play it or move it, press and hold for the card menu (the right-click menu), and double-tap for a double-click.', 'Small screens get the whole table fitted to the screen (pinch to zoom still works). Phones are asked to turn sideways, because the table needs the width.', 'The deck on the Library desk is now one pile per card, its copies stacked underneath, dealt out on a grid that never overlaps. Moving from card to card changes the open book\'s page without the turning leaf, which removes the flicker.'] },
  { v: '0.99.53', title: 'A new logo, and the Library arranged', notes: ['New logo: a temple front (the Library) standing on an open book, in gold. It is used in the top bar, on the Library\'s name plate and as the app icon.', 'The deck on the desk: stacks hold at most three different cards (the basic lands share one stack), the mana-value labels are gone, and the cards are bigger. Hovering a card outlines it in gold instead of lifting it over its neighbours, and the open book turns to its page.', 'The menu book is regrouped. The left page is for playing: your game, the deck in hand, Standard or Commander, who goes first, and Start. The right page is for the Library: Decks, Options and Help.', '"Buy this deck…" is now among a deck\'s buttons in the Library.', 'Library look… (in the menu book): choose the wall (warm plaster, sage, midnight, oxblood, ash grey, wood boards) and the desk (walnut, oak, mahogany, ebony, green baize).', 'Rules: type words side by side now all apply (CR 205.2b). A cost like "Sacrifice an artifact creature" accepts only artifact creatures, and a trigger for "an artifact creature" ignores plain artifacts and plain creatures. Before, either type was enough.', 'Rules: costs that say nontoken, token, noncreature (or any non-type), colorless, multicolored, basic, legendary or tapped now work. Before, they matched nothing (could not be paid) or ignored the word. "A red or green creature" now means a red creature or a green creature.', 'Rules: every card drawn triggers "Whenever you draw a card" (CR 121.2). Before, only the first three cards of one draw did.', 'Rules: "a white or green creature" in a trigger now matches a creature of either colour. Before, only the first colour was checked.'] },
  { v: '0.99.52', title: 'Turn to the card', notes: ['Hovering a card laid out on the desk now turns the open book to that card\'s page: its picture on the left, and on the right its name, cost, type, rules text, power and toughness, and how many the deck has. Move off the cards and the book turns back to the deck. The cards on the desk only lift a little now instead of zooming.', 'Fixed: going back to the Library from a game could show an empty screen. The Library\'s fade-out stayed on it, so it opened invisible the next time. This was also behind the "crash" when changing decks mid-game.', 'The deck button in the top bar is now "Return to the Library". Your game is kept, and "Back to the table" (or Esc) returns to it.'] },
  { v: '0.99.51', title: 'The deck on the desk', notes: ['When you take a book down, its main deck is laid out on the desk below: one column per mana value (0 to 7+, lands last), each card once with its count, fanned so every name shows. Hover a card (or tab to it) to lift it to full size.', 'The deck details on the open book are now set as two proper pages: the deck on the left; key cards and the buttons on the right.', 'Books are solid now: a page block shows at the top, the bottom and the fore-edge, so a book taken down from a high shelf no longer looks hollow from underneath.', 'The title plate is lettered in Cinzel Decorative with a gold finish.', 'Clicking a book on the shelves always takes that book: the side of the book next to it, seen at an angle, could catch the click before.', 'Starting a game from the Library while one is in progress first clears any windows the old game left open. If the game cannot start, you get a message on the table instead of a blank screen.', 'The desk top is now a picture already drawn in the room\'s perspective. It looks the same but is much lighter on the graphics card than the huge 3D surface it replaces.'] },
  { v: '0.99.50', title: 'One room, one view', notes: ['The Library is now drawn as a real room seen from one spot: you sit at a desk facing a wall. Everything shares the same eye line, so the high shelves show their undersides, the lower ones sit near eye level, and the desk top runs towards you. Nothing is drawn from two different angles any more.', 'Four floating shelves of ten books hang on the wall, two on each side of a wooden name plate. With more than 40 decks, arrows on the plate turn to the next shelves.', 'The menu book leans on a stand in the middle of the desk. When you take a book down, it stands on the desk beside it and its details (colours, curve, key cards, notes and the buttons) fill the open book\'s pages.', 'The flight from shelf to desk is worked out in the room itself: the book slides forward out of its slot, arcs over and comes down onto the desk, growing as it comes closer. The neighbouring books show the gap it leaves.', 'The whole scene scales to fit the window.'] },
  { v: '0.99.49', title: 'Floating shelves', notes: ['The Library is redrawn: your decks stand on floating wooden shelves hung on a plastered wall, seen from a little below, and the menu book lies open on a wooden desk. The wood grain is drawn by the app itself, so it needs no downloads.', 'Click any book to take it down, even while another one is on the desk: the two swap places, one floating back to its slot as the other comes down. No need to press "Put it back" first.', 'The book now floats from its slot to the desk in one smooth arc, turning to its cover on the way and settling onto its shadow. Putting it back plays the same path in reverse, even if you change your mind mid-flight.', 'The candle has been taken off the desk.', 'Library viewer: just looking through your library no longer shuffles it, so a scry (or any card you put on top or bottom) stays where you put it. Taking a card out of the library still ticks "Shuffle when closed", as a search should. A new "Library order (top first)" view shows the real order, next draw first and the bottom card last.', 'Checked by the tests: scry sends cards to the bottom in the order chosen and keeps the rest on top, and the shuffle puts every card in every position equally often.'] },
  { v: '0.99.48', title: 'The Library', notes: ['NEW: every session opens in the Library. Your decks stand as books on the shelves; on the reading desk an open book is the menu (Continue your game, New game, Standard or Commander, who goes first, Import a deck, Settings, Accessibility, Rules & help, What\'s new), lit by a flickering candle.', 'Click a book to lay it on the desk: it turns to its cover and shows its colours, curve, key cards and the librarian\'s notes, then "Begin a game with this deck" starts the game and the Library fades into the table.', 'Librarian\'s notes: each deck remembers how often you opened it, when you last did, the average lands in the hands you kept, mulligans per game, and the turn your goldfish kills come on. All of it comes from your own games.', 'The deck button at the top left now takes you back to the Library; Esc (or "Back to the table") returns to your game. You can turn off "Open the Library when the app starts" on the desk.'] },
  { v: '0.99.47', title: 'Prepared, and a New Game reminder', notes: ['RULES (CR 722, prepared): preparation cards such as Carnivorous Cultivator // Enroot now work. From your hand you cast only the creature. When it becomes prepared ("enters prepared", or an effect that prepares it) a copy of its spell waits in exile, marked PREPARED on the creature. Cast it from the creature\'s menu or the exile zone for the spell\'s own cost and timing; casting it unprepares the creature, even if the copy is countered, and the copy never goes to your graveyard. A creature can\'t be prepared twice, and leaving the battlefield ends it.', 'When you pick a different deck, the New Game button glows until you start a game with it, so you know the table still has the old deck.'] },
  { v: '0.99.46', title: 'Deck scan report includes your full lists', notes: ['The deck scan report (deck screen \u2192 Scan decks & save report) now ends with the full list of every deck, including sideboards and any sideboarded list in use, so your decks can be rebuilt exactly for testing.', 'FIXED: the report always said "Card data loaded: NONE" even when your card data was loaded.'] },
  { v: '0.99.45', title: 'Library of Alexandria: dredge, Omniscience, suspend, Hogaak', notes: [
    'The app is now called Library of Alexandria. Your decks, settings and updates are untouched (it keeps the same data folder and update channel).',
    'RULES (dredge, CR 702.52): dredge now replaces ANY draw (cycling Street Wraith, Gitaxian Probe, a trigger), not only the draw step. Cards milled together are one event, so Narcomoeba, Creeping Chill and the like trigger together and you choose their order (CR 603.3b).',
    'RULES (graveyard creatures): Prized Amalgam and Flayer of the Hatebound trigger only for a creature that entered from your graveyard (or was cast from it); Amalgam returns tapped at the next end step. Bloodghast returns itself on landfall. Ichorid exiles another black creature card to come back. Golgari Thug puts a creature card on top of your library.',
    'RULES (Hogaak): "You may cast this card from your graveyard" now gives it a Cast button in the graveyard, and "You can\'t spend mana to cast this spell" is enforced: it is paid only by convoke and delve. Convoke now pays hybrid mana ({B/G}) with a black or green creature (CR 702.51a).',
    'RULES (Omniscience, CR 118.9): "You may cast spells from your hand without paying their mana costs" adds a free way to cast each spell in your hand.',
    'RULES (no mana cost, CR 118.6): Ancestral Vision, Lotus Bloom, Living End and other cards with no mana cost can no longer be cast for free from your hand; clicking one suspends it, and it is cast when its last time counter is removed.',
    'FIXED: a card with no mana cost or a split card (Fire // Ice) made the app loop forever when its mana value was needed, which could freeze the deck screen.',
    'Deck screen: a click takes a book off the shelf straight away, with a smoother take-off (it slides out of its slot, then turns to its cover as it flies to the middle). New Delete deck button (it asks first).',
    'The stack window stays in one place as spells are added (it grows downward). During the opening hand only the game board is dimmed; the top bar, life totals and side panel stay bright.'] },
  { v: '0.99.44', title: 'Amulet Titan rules check, New Game clean-up, deck shelf by click', notes: [
    'RULES (Amulet Titan check): Amulet of Vigor now triggers only for a permanent that enters tapped (CR 603.6a) and untaps that permanent. Bounce lands return a land you choose as the ability resolves (CR 608.2c). Lotus Field sacrifices the two lands you choose. Explore gives a real extra land play this turn. Scapeshift and Genesis Device sacrifice any number of lands, then search for that many. Spelunking puts a land from your hand onto the battlefield (a Cave gains you 4 life), and Cultivator Colossus repeats while you keep putting lands.',
    'RULES: Vesuva and Echoing Deeps are read from their current wording ("this land enter tapped as a copy"); Echoing Deeps copies a land card in a graveyard and is also a Cave. Cards that say "this land", "this creature" and so on are now always understood to mean themselves.',
    'RULES: Summoner\'s Pact sets up "pay {2}{G}{G}; if you don\'t, you lose the game" at your next upkeep, with Pay and Don\'t pay buttons. A turn now stops in the upkeep (or draw step) while a triggered ability there is waiting, instead of running on to Main 1 (CR 503.1).',
    'RULES: Green Sun\'s Zenith is shuffled into your library as it resolves (CR 608.2n). Shifting Woodland and The Mycosynth Gardens become copies of the card you choose (the Woodland only until end of turn). Malevolent Rumble no longer shows the Spawn token\'s mana ability as its own.',
    'FIXED: pressing New Game could leave old cards on screen. Every card of the old game now flies back into the library before the new seven are dealt.',
    'Deck shelf: hovering only lifts a book a little; click a book to take it off the shelf and see its cover (Put it back returns it). A deck that cannot be drawn no longer stops the deck screen from opening: it shows as a plain book, and if the whole shelf ever fails you get a simple list instead.',
    'Linux: the AppImage no longer shows a black window on systems where Chromium cannot use /dev/shm (GitHub issue #83).'] },
  { v: '0.99.43', title: 'Delver: look before you reveal; transformed cards show their back art', notes: ['CHANGED (rules, CR 701.16a): Delver of Secrets and cards like it now show you the top card of your library first. Then you choose Reveal it or Keep it hidden. Only a revealed instant or sorcery transforms it, and the card stays on top of your library either way.', 'FIXED: a transformed card (Delver of Secrets \u2192 Insectile Aberration) could keep showing its front picture. The back face now always shows the back of the card. If you chose a printing for a two-faced card, its back face uses the same printing; Use the default art resets both faces.', 'Mulligan check: watched frame by frame, all seven cards of the old hand fly back into the library (including any that are drawn again) before the new seven is dealt. This needs v0.99.42 or later.'] },
  { v: '0.99.42', title: 'Decks are books on a bookshelf', notes: ['The deck screen is now a real bookshelf: each deck is a book standing spine out with its name and colours on the spine, ten books to a shelf. Hover a book (or move to it with Tab) and it slides out and turns so you can see its front cover with the deck art. Click it to take it off the shelf (details, mana curve, Use this deck, Edit, Sideboard, art), Escape to put it back, double-click to use it straight away. The deck in use has a gold bookmark ribbon.', 'Each book is the deck\'s main colour (the colour with the most mana symbols in the deck; a deck with no coloured spells goes by its basic lands): white, blue, black, red, green, or grey for colourless.', 'FIXED: after a mulligan, a card that was drawn again in the new seven looked as if it had never left your hand. The rules were already right (CR 103.5: the whole hand goes back, the library is shuffled, a new seven is drawn); now the screen shows it too: all seven cards fly back into the library before the new hand is dealt.'] },
  { v: '0.99.41', title: 'Class enchantments have levels', notes: ['FIXED (rules, CR 716): Class enchantments such as Stormchaser\'s Talent had all of their abilities at once, so the level-3 "whenever you cast an instant or sorcery spell, create an Otter" made tokens from the start. A Class now enters at level 1 and has only the abilities of the levels it has reached. "{cost}: Level N" is offered as an ability, at sorcery speed, only from level N-1; "When this Class becomes level N" triggers when it levels up; a Class that leaves the battlefield starts again at level 1.', 'The same "only what it has reached" reading now also decides the triggered and static abilities of Spacecraft (station levels).'] },
  { v: '0.99.40', title: 'Deck bookcase, tidier Settings, mulligan to zero, Spacecraft text', notes: ['NEW: the deck screen is a bookcase. Deck boxes stand on wooden shelves; hovering slides one forward, and a click takes it off the shelf into the middle of the window, where you can turn it with the mouse and see its colours, mana curve and key cards next to Use this deck, Edit list, Sideboard, Box art and Card art & printings. Escape or Put it back returns it; a double-click still picks a deck at once.', 'Settings reorganised: Playmat & frame has its own tab, the teaching aids are grouped (Turn flow, Casting & the stack, On the cards, Help & the log) in two columns, the rows are tighter, and search now finds a single switch inside a group. A duplicate "Replacement effect notes" switch was removed. Every option and every accessibility setting is still there; the columns drop to one when the text is large.', 'FIXED: a window opened during the opening hand (Settings, for example) was drawn underneath the large hand cards.', 'RULES (CR 103.5): a mulligan always puts the whole hand back, shuffles and draws a new seven; you may now mulligan all the way to zero cards (it used to stop at one).', 'FIXED (rules): keyword costs written "Keyword\u2014Cost." (Cumulative upkeep\u2014Pay 1 life., and similar) were not read because the line ends in a period.', 'FIXED (rules): Spacecraft now read their real Oracle text ("10+ | Flying" lines, with the power and toughness box at the threshold the reminder text names), so they are only creatures, and only get those abilities, once they have enough charge counters.', 'Tests: the invented test cards are now kept in the repository, and all 237 rules checks pass.'] },
  { v: '0.99.39', title: 'Tribal Flames and "where X is" counting fixed; Card art grid tidied', notes: ['FIXED (rules): Tribal Flames and other Domain cards dealt 0 damage. "X is the number of basic land types among lands you control" is now counted (with Leyline of the Guildpact or Prismatic Omen out, each land you control has all five types, so one land gives 5; with no lands it is 0).','FIXED: a "where X is the number of ..." that the app cannot count is never taken as 0 any more. The line is left for you to do by hand (and shown as not understood) instead of quietly doing nothing. "The number of cards in your graveyard" now counts the graveyard (it used to give 0).','Card art & printings: the buttons fit inside each card (Printing\u2026 on its own row), and every card lines up.'] },
  { v: '0.99.38', title: 'Damage targeting fix', notes: ['FIXED (rules): spells and abilities that deal damage to "target creature or planeswalker" (Strangle, Burning Hands, Broadside Barrage and about 60 others) were offered as damage to the opponent. A player is not a legal target for them (rules 115.1 and 601.2c), so that option is gone. "Any target", "target creature or player" and "target player or planeswalker" still offer it.'] },
  { v: '0.99.37', title: 'Choose printings (alternate art) and buy the deck', notes: ['Card art & printings (Deck view, or Deck boxes \u2192 art): every card has a Printing\u2026 button that lists all of the card\u2019s real printings from Scryfall with their pictures. Pick one and that art is used for the card in this deck, on the table, in your hand and in the preview. Use the default art goes back. Your own pictures still work as before.','Buy this deck (Deck view): opens TCGplayer Mass Entry in your browser with the deck filled in, using the exact printing you chose for each card (other cards are left to TCGplayer). Nothing is bought until you check out there. Copy list with set codes puts the list on the clipboard for any other store (Card Kingdom, Mana Pool, a local store).'] },
  { v: '0.99.36', title: 'Opening hand, attack requirements, triggers on the stack, choice costs', notes: ['Opening hand: the large, centred hand is only for deciding whether to keep or mulligan, so you can read every card. From Keep on (putting cards on the bottom, Pre-game actions, your first turn) it is the normal hand. The prompt and the hand sit together in the middle of the table.','Mulligan and new game: you see the whole hand go back into the library, the library shuffle, and the new seven dealt one at a time (rules 103.2 and 103.5). Shuffles were already correct (an unbiased Fisher-Yates shuffle with cryptographic randomness); this is now checked by statistical tests.','The card you choose for a mulligan is stamped BOTTOM, not DISCARD (the stamp now says what happens to the card).','FIXED (rules): a creature that "attacks each combat if able" (Dragon\u2019s Rage Channeler with delirium, Goblin Rabblemaster\u2019s Goblins...) no longer attacks by itself. The Declare attackers window opens with it already chosen and locked, and you may add other attackers (rule 508.1d). Clicking a later step or Next turn also stops at declare attackers instead of skipping the requirement.','Triggered abilities go on the stack by themselves (rule 603.3): there is no "Put on the stack" button for a single ability. You are asked only for its targets or modes; if several abilities trigger at once, a window asks for their order (rule 603.3b). A "you may" choice is made when the ability resolves (rule 603.5).','FIXED (rules): an additional cost with a choice, such as Lightning Axe\u2019s "discard a card or pay {5}", is read as two ways to cast the spell (rule 601.2b); each is offered when you can pay it.'] },
  { v: '0.99.35', title: 'A smoother opening hand; the stack shown on top of the table', notes: ['Opening hand: your seven cards are dealt one at a time from the library, and the Opening hand box appears once the last card has landed. After a mulligan the old hand goes back to the library first, then the new one is dealt.','The hand keeps one size from the deal, through mulligans and choosing cards for the bottom, to the Pre-game actions screen, and only goes back to normal size when your first turn begins. On a small window it takes the size that fits every step instead of changing between them.','Pre-game actions shows the first sentence of each card (the full text is in its tooltip), so the screen stays compact.','Stack: the stack panel in the middle of the table is now solid and always on top. Your board is dimmed behind it, your cards and permanents stay usable so you can respond, and the panel shrinks to fit above your hand, so no card or zone covers it or its buttons.'] },
  { v: '0.99.34', title: 'UI check: top bar on wide screens, tidier start of game', notes: ['FIXED: on wide windows (over 1700 pixels) the top bar labels (Undo, Shuffle, Draw, Untap all, Token, Stack) were squeezed into small square buttons, overlapped each other and covered the next button, so a click could hit the wrong one. They now get their full width.','The Pre-game actions screen only appears when a card in your opening hand can actually do something before the game (Leylines, opening-hand reveals...). It no longer stops every game just to say there is nothing to do.','The Opening hand box no longer says "Your hand is shown below."','Pop-ups opened during the opening hand (for example Deck view) now fit above your hand and scroll, instead of running off the top of the window.','The "Download card data?" prompt closes by itself once card data has been loaded from a file.'] },
  { v: '0.99.33', title: 'X counters fixed, animated artifacts show their P/T, no floating Hand bar', notes: ['FIXED (rules): "enters with X +1/+1 counters" was applied twice. Walking Ballista cast with X = 3 (paying 6 mana for {X}{X}) now enters with 3 counters, not 6; Hangarback Walker and every other X creature likewise. X counters still go through Hardened Scales and similar effects once, and a permanent that enters without being cast has X = 0 (rule 107.3m). "Twice X" is read too.','FIXED: when an effect sets a creature\u2019s power and toughness (Karn, the Great Creator making an artifact a creature, a land that becomes a creature, "base power and toughness N/N"), the P/T box now shows on card pictures. The new value was treated as the printed one, so with images on nothing was shown (rule 613.4b). Hover the box to see which effect set it.','The floating Hand bar over your hand is gone. The Card outline key (what the green, red and gold outlines mean) is now in the \u2630 Game tools menu and opens in a normal window.','FIXED: How the app reads cards no longer fails on 837 cards (Magma Sliver, Flashback and others) when no game is running.'] },
  { v: '0.99.32', title: 'Sacrifice-for-mana sources pay like lands; clearer opening hand', notes: ['FIXED (rules): mana abilities whose cost is a sacrifice (Eldrazi Spawn and Scion, Treasure, Gold, Lotus Petal and any card worded the same way) now count as mana sources (rule 605.1a). Your hand shows spells as playable when those sources can pay, and paying a cost uses them automatically: lands and other mana sources first, then the sacrifice sources, which are sacrificed as you pay (no stack, rule 605.3b). "Dies" and "leaves" abilities trigger as usual.','A sacrifice-only mana ability (no {T}) works while the creature is summoning sick or tapped (rule 302.6). A double-click or the tap toggle never sacrifices it by accident: use the ability menu, or simply cast the spell.','FIXED (rules): a {C} symbol in a cost is paid only with colourless mana (rule 107.4c). Before, any land could pay it.','The payment window marks sources that will be sacrificed, and How the app reads cards explains sacrifice mana abilities.','Opening hand: the hand is sized to fit inside the table (and below the Opening hand box) at every window size, measured with the cards fanned out. The Opening hand box is no longer dimmed: it sits above the dark layer with a gold outline so it is clearly the thing to click.'] },
  { v: '0.99.31', title: 'Echo, persist, undying, Spacecraft, creature-type choices, uncounterable spells', notes: ['NEW (rules): Echo (702.30) asks for the echo cost at your next upkeep or sacrifices the permanent; Persist (702.79) and Undying (702.93) return the creature with a -1/-1 or +1/+1 counter only if it had none of that kind when it died (last known information); "Sacrifice it unless you ..." (Glint Hawk style) is a choice between doing the cost and losing the permanent.', 'NEW: Spacecraft and Station (702.184, 721): Station taps another creature and adds charge counters equal to its power; at each STATION N+ threshold the card gains the lines under it, and at the highest one with a power/toughness it is an artifact creature (Borg Cube: 6/6 at 12). Assimilate (701.72) is read from the Borg Cube text.', 'FIXED (engine): "As this creature enters, choose a creature type" (Roaming Throne) was not recognised because it does not say "the battlefield". The picker now lists creature types on the battlefield first, then in your deck, and a typed answer must be a real creature type. Roaming Throne is the chosen type too and makes triggers of other creatures of that type trigger an additional time.', 'NEW (engine): "Can\'t be countered" is one check for every counter effect: the spell\'s own text, statics such as "Green spells you control can\'t be countered", and mana such as Cavern of Souls ("and that spell can\'t be countered"). The Countered button then reads "Can\'t be countered".', 'Opening hand now always fits the window. Hand Key sits at the far right of the hand bar and opens an opaque window. Commander mode piles run Deck, Commander, Graveyard, Exile; hovering any pile shows its top card (your commander for the command zone).'] },
  { v: '0.99.30', title: 'Commander decks have their own tab', notes: ['Click the deck name: the deck screen now has a Decks | Commander switch. Commander mode is chosen there; Commander decks (a Commander section in the list) are only listed in Commander mode and normal decks only in normal mode. In Commander mode a gold Commander mode chip shows beside On the play; click it to go back to the deck screen.','Saving or importing a deck of the other kind switches to its mode so you can see it. Importing in Commander mode starts with a Commander heading ready.'] },
  { v: '0.99.29', title: 'Commander mode (goldfish)', notes: ['Put your commander under a Commander heading in the deck list (or mark it *CMDR*). A Commander switch appears beside On the play.','Rules enforced: 40 life, 99-card library, a command zone pile, casting it from there costs {2} more per previous cast, a free first mulligan, and the choice to put it back into the command zone when it would go to the graveyard, exile, hand or library (CR 903.9). Commander combat damage to your opponent is tracked (21 is lethal).','A deck check at the start of a game reports the card count, singleton and colour identity problems.'] },
  { v: '0.99.28', title: 'Accessibility tab, mulligan fix, centred pop-ups', notes: ['Mulligan hand fixed: it stays inside the table layout (the fixed-position version could land off-screen on some windows). A test now checks it at several window sizes.','Pop-ups now all open at the same place, the centre of the window; only the stack and resolving panels keep their own spots, and the mulligan steps sit above the hand.','The One Ring and other "for each counter" text: Always Yield now still recognises the action while the live count changes.','⚙ → Settings → Accessibility: interface size (100–175%), high contrast, calm motion (no animation, tilt, fan or scrolling text), larger click targets, strong keyboard focus, and screen-reader announcements of the game log. More options are planned (colour-blind markers, full keyboard play, a text view of each zone).'] },
  { v: '0.99.27', title: 'Bigger opening hand; Ancient Stirrings read in full', notes: ['The opening-hand screen (Keep / Draw / Mulligan) now shows your hand large and centred so every card can be read.','"Look at the top N cards. You may reveal a [type or colorless] card from among them and put it into your hand. Put the rest on the bottom" is now read in full (Ancient Stirrings and similar): at most one card, only cards of that kind.'] },
  { v: '0.99.26', title: 'Multi-step abilities apply every step (Orcish Bowmasters)', notes: ['An ability like "deals 1 damage to any target. Then amass Orcs 1." is now one button that applies every step in written order, instead of one button per step where the later steps were easy to miss. Always Yield repeats the whole chain too, not just the first step.'] },
  { v: '0.99.25', title: 'Opponent search asks what they searched for; bigger mulligan hand', notes: ['The opponent-search button now asks what your opponent searched for (basic land, other land, creature, other card, or nothing). "Whenever an opponent searches their library for a land card" abilities only trigger for a land search.','Opposition Agent: you name the card they found, it is exiled, and you may play it for as long as it stays there, spending mana as though it were any colour. "Your opponents can\'t search libraries\" (Stranglehold) now stops the search.','Mulligan: the hand rises, enlarges and centres on the table under a "Select X cards and put them at the bottom to continue" box.'] },
  { v: '0.99.24', title: 'Barrowgoyf-style "mill that many, then take one"', notes: ['The amount an event carried (combat damage dealt, life gained or lost) now reaches the triggered ability, so "that many" is a real number.', 'New reader for "Mill N. If you do, you may put a creature (or other type, or mana value limit) card from among them into your hand or onto the battlefield": only the cards that mill put in the graveyard are offered, not the rest of it.'] },
  { v: '0.99.23', title: 'News-ticker status text and a matching mulligan bar', notes: ['Top-bar status chips whose text is too long (Images 20/23, Card data…) now scroll sideways and back, news-ticker style, instead of being clipped.', 'The mulligan "put on the bottom" bar and the discard bar now use the same panel look, accent colours, pill counter and buttons as the rest of the game.'] },
  { v: '0.99.22', title: 'Auras and Equipment stack under their host', notes: ['NEW: an Aura or Equipment is now drawn in a stack with the permanent it is attached to, the same cascade as a land pile: the host sits in front and each attachment shows its name strip above it. The "attached" tag on each card stays as it was.', 'CHANGED: piles no longer print the land or artifact name under them, since the cascade already shows each name. The colour and Tapped labels stay.', 'CHANGED: the Hand / Key tag now sits permanently in the bottom-right corner, level with the bottom of your hand.']},
  { v: '0.99.21', title: '3D tilt on every card; multiplayer switched off', notes: ['CHANGED: cards on the battlefield now lean toward the pointer in 3D just like the cards in your hand and the big preview (a tapped card keeps its turn). It follows Settings > Animations > 3D card tilt.', 'CHANGED: Multiplayer (LAN) is switched off for now and its menu entry is hidden until it is in a better place. The code is kept and can be switched back on.']},
  { v: '0.99.20', title: 'Big card preview follows the pointer again', notes: ['FIXED: the enlarged card preview in the right column now leans toward the pointer in a soft 3D tilt with a light spot, and settles back when the pointer leaves it. It had only moved for foil cards. It stays still if your system asks for reduced motion.']},
  { v: '0.99.19', title: 'Artifact piles and a calmer turn bar', notes: ['NEW: non-creature artifacts pile the way lands do. Mana artifacts (Sol Ring, Mox Opal...) pile by the colours they make, identical artifacts pile together, an artifact with an activated ability (Equipment and the like) only piles with exact copies, and all tapped artifacts share one sideways Tapped pile. Artifact creatures and tokens are not piled this way (tokens still bundle in fives). The same Settings > Layout switch controls it.', 'CHANGED: the progress fill in the turn bar is now a flat tint with a slim accent line along the bottom, the same look as the other bars, instead of animated stripes with a glow.']},
  { v: '0.99.18', title: 'Automatic targets and smarter Always yield', notes: ['NEW: a triggered ability with exactly one legal choice picks it by itself (CR 603.3d), so a trigger whose only possible target is your one creature goes on the stack with no window. The log says what it chose.', 'NEW: Always yield remembers what the ability could target when you set it. If a new possible target has appeared (or one has gone) since, the app asks you to choose again and then remembers the new choice. Turn Always yield off any time in the gear menu under Always yield; the log line for an automatic trigger now says so.']},
  { v: '0.99.17', title: 'Metalcraft cards now work, ability words are just labels, protection', notes: ['FIXED: Metalcraft cards were shown as "count it yourself". An ability word (Metalcraft, Threshold, Delirium, Revolt, Morbid, Landfall and the rest) is only a label with no rules meaning (CR 207.2c), so the app now reads each line without it and the condition inside the sentence does the work: "Metalcraft \u2014 ~ gets +2/+2 as long as you control three or more artifacts" is a live +2/+2, and "Metalcraft \u2014 deals 4 damage instead if you control three or more artifacts" replaces the plain damage while Metalcraft is on.', 'CHANGED: the top-bar game-state checks (Metalcraft, Threshold, Delirium, Revolt, Morbid) are now the one source of truth for those conditions, so a card and its icon can never disagree.', 'NEW: protection (CR 702.16b). A permanent with protection from a colour (printed, or granted such as Etched Champion\'s "protection from all colors as long as you control three or more artifacts") cannot be chosen as a target by your own spells and abilities of that colour.', 'FIXED: a conditional "instead" sentence with nothing before it could stop a card from being read at all.']},
  { v: '0.99.16', title: 'Metalcraft and other conditional "instead" lines', notes: ['FIXED: a line such as "Metalcraft \u2014 Galvanic Blast deals 4 damage instead if you control three or more artifacts" was not understood. The app now reads any "X instead if [condition]" or "If [condition], X instead" sentence (CR 614.1a), for Metalcraft, Threshold, Delirium and the other ability words (CR 207.2c): when the condition is true it replaces the sentence before it, keeping that sentence\'s targets, and when false it is left out. A condition the app cannot check is still reported as not understood.', 'NEW: "seven or more cards are in your graveyard" (the printed Threshold wording) is understood as a condition.']},
  { v: '0.99.15', title: 'Tapped land pile lies sideways', notes: ['CHANGED: the Tapped pile now shows its lands turned sideways, overlapping left to right so each land\'s name stays readable along its edge, instead of dimmed upright cards. Hover a land to bring it to the front.']},
  { v: '0.99.14', title: 'Incubate, and a clearer attack window', notes: ['NEW: Incubate N (CR 701.53) creates an Incubator token with N +1/+1 counters. Its "{2}: Transform this artifact" turns it into a 0/0 Phyrexian artifact creature that keeps its counters (CR 701.28, 111.10).', 'CHANGED: in the Declare attackers window, "Attack with all" and "Clear" now sit below the list of creatures, and the combat windows are slightly see-through so you can still read the board.']},
  { v: '0.99.13', title: 'Trigger filters: nontoken, token, nonland', notes: ['FIXED: Weapons Manufacturing and Kappa Cannoneer built an endless chain of triggers. A trigger filter such as "nontoken artifact" did not exclude tokens, so the Munitions token it made triggered it again. Trigger filters now read the whole qualifier for any card: "nontoken" and "token" (CR 111.1), and "nonland", "nonartifact", "noncreature", "nonenchantment", "nonlegendary" (CR 205.4b). A token is judged by its own types, since it has no printed card.']},
  { v: '0.99.12', title: 'Land piles by colour and token bundles', notes: ['NEW: lands pile by what they do. Untapped lands that make the same colours share one pile (all your {G} lands together, all {U}/{B} lands together), every tapped land goes into one Tapped pile, and a land with an activated ability (fetch lands, Wasteland, manlands) only piles with exact copies of itself until it is tapped. A pile is a cascade like the deck view, so the name of every land stays readable; click one land to tap or untap just that land. Tapped lands in a pile are dimmed rather than turned sideways so their names still read. Turn it off with Settings > Layout > Land piles by mana colour.', 'NEW: identical tokens bundle in fives. Two fives make a ten, five tens a fifty, two fifties a hundred, and so on up to a thousand, each with a count and a stronger colour as it grows, so an infinite-token engine is easy to see. Fewer than five stay as separate tokens; click a bundle to spread the whole group out.']},
  { v: '0.99.11', title: 'Only usable tokens', notes: ['CHANGED: the offline token set now holds only tokens that can appear in a paper game. Joke / Un-set and memorabilia tokens are left out, and entries that differ only by artwork, colour order or reminder text collapse into one. Older saved token lists are replaced by a fresh filtered download on next start.']},
  { v: '0.99.10', title: 'Always yield is per card', notes: ['FIXED: "Always yield" was remembered by card name, so a second copy of the same card (Kappa Cannonier, for example) reused the first copy\'s targets. It is now tracked per individual card: cast a second copy, pick its targets, and choose Always yield again if you want it (CR 603.5, 601.2c).']},
  { v: '0.99.9', title: 'Attack requirements, quoted token abilities, and every token offline', notes: ['NEW: "Attacks each combat if able" (Dragon\'s Rage Channeler when delirious, Goblin Rabblemaster\'s Goblins, and the same wording on any card or Aura) is now enforced (CR 508.1d). The attack helper pre-selects the creatures that must attack, shows why, and will not let you untick them; skipping attacking still sends them in.', 'FIXED: a quoted ability on a token a card creates ("create a token with \'Whenever this creature attacks, ...\'") was read as the card\'s own ability, so Weapons Manufacturing skipped its token (CR 111.4, 113.3). Quoted text now belongs to the thing it is given to; the card is read without it. Emblems and granted abilities keep their quotes.', 'NEW: every official token and emblem is downloaded from Scryfall on first start and with each card-data load, then saved offline like the cards (refreshed monthly). The status chip shows the token count, so the engine knows every token a deck might create.']},
  { v: '0.99.8', title: 'Vehicles, repeatable modes, and stricter always-yield', notes: ['NEW: Crew (CR 702.122). Right-click a Vehicle, choose Activate, and pick untapped creatures with total power at least the crew number (summoning-sick ones may crew); they tap and the Vehicle becomes an artifact creature with its printed power and toughness until end of turn.','NEW: "Choose three. You may choose the same mode more than once" (Mystic Confluence): each mode has a + / − counter; repeated draws add up and a repeated targeted mode gets its own target (CR 700.2d).','NEW: "Reveal the top card of your library. If it\'s a land card, put it onto the battlefield. Otherwise, put it into your hand." (Coiling Oracle) and the Ad Nauseam loop (reveal, put into hand, lose life equal to its mana value, repeat as often as you like) are applied by the app.','FIXED: "Always yield" now only applies to plain abilities. A "you may" ability or one with an "if"/"unless" condition always asks you on resolution (CR 603.5, 603.4), and an ability with a line the app cannot apply is never auto-resolved.','FIXED: Aura "Enchant …" lines show as understood (the app already makes you choose a legal host and puts the Aura into the graveyard if there is none).'] },
  { v: '0.99.7', title: 'Rules dive 2: global statics, devotion, top-of-library play', notes: ['NEW: Winter Orb / Static Orb ("players can\'t untap more than one land / two permanents") ask which ones untap; Sulfuric Vortex stops life gain; Containment Priest exiles a creature that enters without being cast; Rhonas and similar "can\'t attack or block unless you control another creature with power 4 or greater" are enforced; Humility-style "All creatures lose all abilities and have base power and toughness 1/1" applies to every creature.','NEW: "where X is your devotion to blue" (Thassa\'s Oracle, including its win check), "Add {B} for each Swamp you control" (Cabal Coffers), Nykthos\'s devotion mana, and "you win the game" are all read from the text (CR 700.5).','NEW: Courser of Kruphix and Oracle of Mul Daya: the top card is shown revealed under your library, and the library menu has "Play the top land", which uses your land drop.','FIXED: Torpor Orb\'s real wording ("Creatures entering the battlefield…") is recognised; Oracle-shortened names like "Rhonas" count as the card itself; lord and loyalty lines such as "−X:" (Ugin) now show as understood; Time Warp is read as an extra turn.'] },
  { v: '0.99.6', title: 'Lords, player-choice clauses, and a consistency pass on the look', notes: ['NEW: "Other Merfolk get +1/+1 and have islandwalk", "Other Goblin creatures you control get +1/+1 and have haste" and "Creature tokens you control get +1/+1 and have vigilance" now work: a line that gives both a bonus and an ability is read as two static effects (CR 611.3). Landwalk keywords can be granted.','NEW: "Each player discards a card", "Each player sacrifices a creature" and "Target player sacrifices a creature" (Liliana of the Veil) let you choose yours; the opponent\'s half is stated in the log. "Untap up to three lands" (Frantic Search) lets you pick which lands. "Look at the top card of your library. You may put it into your graveyard" works.','NEW: "Exile each permanent with mana value X or less that\'s one or more colors" (Ugin, the Spirit Dragon) leaves colourless permanents alone.','LOOK: one shared corner radius for buttons, fields and toolbar controls; stray half-pixel font sizes and odd radii were moved onto the shared scale; the four pixel-art playmats are dimmed so they sit back like the other mats and the zone labels stay readable.'] },
  { v: '0.99.5', title: 'Scaling mana: Elvish Archdruid, Gilded Lotus', notes: ['NEW: "{T}: Add {G} for each Elf you control" (and any "for each <thing> you control") is counted when you tap, so the right amount floats (CR 106.1, 605.1a).','NEW: "{T}: Add three mana of any one color" (Gilded Lotus) gives three mana of the colour you choose.'] },
  { v: '0.99.4', title: 'Rules dive 2: more death and equipment triggers', notes: ['NEW: "Whenever ~ or another creature dies" (Blood Artist style) now also triggers on its own death (CR 603.10a).','NEW: "Whenever equipped/enchanted creature dies, attacks, or deals combat damage" triggers on the Equipment or Aura (Skullclamp, Sword-style cards); the creature\'s death is remembered even though the attachment falls off (CR 603.10a, 301.5).'] },
  { v: '0.99.3', title: 'Rules dive 1: mass effects, hand effects, kicker, and more cards fully read', notes: ['A broad check of 93 well-known cards against the rules-text reader found 41 with lines the app only partly read; this release brings that to 11, and the rest are honest limits (the opponent\'s hand, board and library are not tracked in a goldfish game; divided damage; Balance-style choices).', 'NEW mass effects, read from the rules text: "Destroy all creatures / lands / each artifact, creature, and enchantment with mana value X or less", "Exile all ...", "Return all ... to their owners\' hands", "Tap / Untap all ..." with other / nonland / non-colour / tapped / power / mana value / keyword qualifiers (Wrath of God, Armageddon, Pernicious Deed...). Indestructible permanents survive; "can\'t be regenerated" is accepted.', 'NEW hands: "Each player discards their hand, then draws seven cards" (Wheel of Fortune, Windfall asks how many your opponent discarded), "Each player shuffles their hand and graveyard into their library, then draws seven" (Timetwister), "Draw three cards, then put two cards from your hand on top of your library in any order" (Brainstorm, with an ordering window), "You may put a land card from your hand onto the battlefield" (Growth Spiral).', 'NEW kicker: "If this spell was kicked, it deals 4 damage instead" (Burst Lightning) and "If this spell was kicked, ..." riders are applied when it resolves.', 'NEW look-at-the-top sorting can put cards onto the battlefield with a cap and a filter ("put up to two creature cards with mana value 3 or less ... onto the battlefield", Collected Company; buttons are disabled for cards that do not qualify).', 'NEW target-player compounds: "Target player draws two cards and loses 2 life" (Sign in Blood), "mills two cards", "discards two cards (at random)"; opponent halves that are not tracked are logged, not skipped.', 'NEW: Swords to Plowshares-style "Its controller gains life equal to its power" and Path to Exile-style "may search for a basic land", "Destroy target creature if it has mana value 2 or less" (Fatal Push), Oblivion Ring\'s paired enter / leave effects, "Return ~ to its owner\'s hand" (Rancor) and "put this artifact on top of its owner\'s library" (Sensei\'s Top), Gamble\'s random discard, Duress-style opponent hand reveals (acknowledged, not tracked), and the Suspend line.'] },
  { v: '0.99.2', title: 'Fix: Flow State and "if ..., instead" sorting', notes: ['FIXED: Flow State ignored its graveyard check. "Look at the top N cards ... put one into your hand and the rest on the bottom. If there is an instant card and a sorcery card in your graveyard, instead put two of them into your hand ..." is now read as a base sort plus a conditional "instead" sort (CR 608.2c): when it resolves the app checks the condition and uses the right one (and tells you if it cannot check a wording).', 'NEW condition wording: "there is an instant card and a sorcery card in your graveyard" / "you have a land card and a creature card in your graveyard" (each listed kind must be there), usable by any condition-reading effect.'] },
  { v: '0.99.1', title: 'No more silently skipped lines; Ponder; shuffle animation; themed pointers', notes: ['FIXED (engine): a card line the app only half understood could be dropped without a word. Ponder is the example: only "Draw a card" was read, so the look-and-reorder was skipped and the draw was applied automatically. Now (1) every sentence is checked action by action (look, shuffle, scry, mill, draw, discard, exile, destroy, sacrifice, create, search, put on top/bottom...) and any action the reader did not produce is flagged; (2) an effect with a flagged line is never auto-applied or Always-yielded; (3) the resolve window lists every line the app does NOT apply, with tick boxes, so nothing is skipped silently.', 'NEW: "Look at the top N cards of your library, then put them back in any order. You may shuffle." (Ponder and anything worded like it): you get an ordering window with up/down arrows and a shuffle tick box, then the rest of the effect (draw a card) happens.', 'NEW: "Shuffle it into its owner\'s library" (Blightsteel-style) and "Shuffle your hand and graveyard into your library" (Timetwister-style).', 'NEW: a riffle-shuffle animation over your library every time it is shuffled (search effects, fetch lands, the Shuffle button, Ponder). Turn it off under Settings > Motion & effects > Shuffle animation. Every shuffle now goes through one place, so none can be missed.', 'FIXED: a token whose name is also a creature type (Rat, Pest...) read its own name as "this creature" in rules text such as "for each other Rat you control", so Rat tokens never grew. "Gets +N/+N for each ..." is now read for any countable thing. Aura tokens that set base power and toughness (Cursed Role) now apply.', 'Every one-click set now switches the mouse pointer too: ink quill (Parchment), little galaxy (Pixel cosmos), crescent moon (Midnight), water drop (Abyss), leaf (Forest), neon arrow (Neon), gilded arrow (Obsidian). The pointers are also in Settings > Look & feel > Mouse cursor.'] },
  { v: '0.99.0', title: 'Mana-spent conditions on cast triggers; Dark Matter Manipulator verified', notes: ['NEW: "Whenever you cast a spell, if no mana was spent to cast it, ..." and "if mana was spent to cast that spell" (CR 601.2h, 603.4). The app now records whether any mana was spent when you cast a spell (lands, rocks or floating mana); spells cast for free (cascade, discover, free-cast effects, alternative costs paid without mana) count as no mana spent. The condition is checked as the spell is cast, as the rules require.', 'Checked against its real text: Dark Matter Manipulator (mill three on entering; +2/+0 for every seven cards in your graveyard, counted live in steps of seven). It was already handled by the conditional-static reader and is now covered by a rules test.'] },
  { v: '0.98.9', title: 'Matching mouse pointers for the pixel sets', notes: ['The Pixel mushroom, cats, frog and music sets now switch your mouse pointer too, to a small pixel sprite of the same theme (mushroom, cat, frog, music note) with a white-outlined hover picture.', 'Eight new pointers under Settings > Look & feel > Mouse cursor: the four sprites, plus a pixel arrow in each set colour (mushroom red, cat orange, frog green, music pink).'] },
  { v: '0.98.8', title: 'Four new pixel-art sets: mushroom, cats, frog, music', notes: ['New one-click sets under Settings > Look & feel: Pixel mushroom, Pixel cats, Pixel frog and Pixel music. Each brings its own hand-drawn pixel sleeve, a matching playmat (Settings > Board), interface colours and a song (golden hour, jazz-hop, rainy window and arcade chill). All art is original and drawn in code, so it works offline.', 'The sleeve, playmat and interface theme can also be picked on their own.'] },
  { v: '0.98.7', title: 'Cori-Steel Cutter: flurry and "you may attach", per its rulings', notes: ['FIXED: "Whenever you cast your second spell each turn" (and first / third / fourth, with an optional spell type) was not understood, so the ability fired on EVERY spell. Ordinal cast triggers now count the spells you cast this turn (CR 603.2, 601.2i), including spells cast before the permanent entered the battlefield. A cast-ordinal wording the app cannot read is skipped and flagged instead of guessed.', 'NEW: "Create a ... token. You may attach this Equipment to that token." The token is created first, then you choose whether (and, with several tokens, to which one) to attach it, with nothing able to happen in between (CR 701.3, 301.5, 303.4). Until you do, the Equipment is unattached and gives nothing, because "equipped creature gets ..." only affects the creature it is attached to (CR 301.5).', 'Test: Cori-Steel Cutter second-spell gating, token enters 1/1 with no bonus, then 2/2 trample haste once attached.'] },
  { v: '0.98.6', title: 'Prowess fixed and checked against CR 702.108', notes: ['FIXED: prowess was tagged as a special case, so Always yield and automatic resolving skipped it. It is now an ordinary triggered ability ("whenever you cast a noncreature spell, this creature gets +1/+1 until end of turn"), so Always yield is offered and works.', 'FIXED: any card that merely mentioned the word prowess in its rules text could be treated as having it. Prowess is now read from the keyword line only, or from an effect that gives it.', 'Each instance triggers separately (CR 702.108c), prowess given by another permanent works, and it triggers only on your noncreature spells. Tested end to end: trigger, Always yield, stacking pumps and ending at the cleanup step.'] },
  { v: '0.98.5', title: 'Conditional statics, and the app now knows what it is missing', notes: ['New rules-text reader for conditional and scaling static abilities (CR 611.3, 613.4c): "gets +2/+2 as long as there are three or more land cards in your graveyard", "gets +2/+0 for every seven cards in your graveyard", "as long as it\'s your turn, this creature has first strike". It understands graveyard / hand / battlefield counts by card type or subtype, life totals, hand size, counters on it, tapped / attacking, spells cast this turn and "or more / or fewer / no" wording, joined with "and" / "or". Nothing is keyed to card names.', 'Honest gaps: wording the reader cannot evaluate is never guessed. The line is marked as only a reminder in How the app reads cards, a \u26a0 badge appears on the permanent (hover it to see the lines), the log says so when the card enters, and a conditional power/toughness is shown with a ?. Both aids can be switched off in Settings.'] },
  { v: '0.98.4', title: 'Fix: "when this dies / is put into a graveyard" triggers, and loses-all-abilities effects', notes: ['FIXED: abilities like "When ~ dies" and "When ~ is put into a graveyard from the battlefield" (Flagstones of Trokair) were being dropped, because the check that a card is in the right zone ran after the card had already reached the graveyard. Leaves-the-battlefield abilities now look back as the rules say (CR 603.10a). A test now sends cards to the graveyard by every route (destroy, sacrifice, move, leave) and checks the trigger appears.', 'New: effects that change what a permanent is (CR 613): "loses all abilities", "becomes a blue Frog with base power and toughness 1/1" (Turn to Frog), "loses flying", and Auras such as Kenrith\'s Transformation, Darksteel Mutation, Imprisoned in the Moon and Song of the Dryads (a land that becomes a Forest taps for G and loses its other abilities, CR 305.7). Triggers, keywords, type line, colour, power/toughness and mana follow the new characteristics, and temporary effects end on their own.'] },
  { v: '0.98.3', title: 'Mutate, Splice, spell target filters and a tidier gear menu', notes: ['Mutate (CR 702.140): cast a creature for its mutate cost, target a non-Human creature, and choose over or under. The merged permanent is one creature with every card\'s abilities, keeps its counters and auras, fires "whenever this creature mutates" triggers, and all its cards leave the battlefield together. If the target is gone it resolves as a normal creature spell.', 'Splice onto Arcane (CR 702.47): when you cast an Arcane spell, splice cards in your hand are offered as optional extra costs. The spell gains their effects and they stay in your hand.', 'Counter and other spell-targeting text now honours "with mana value N (or less/greater)", "nonland" style words and colour words when choosing targets on the stack.', 'The gear menu is now only Settings, Update, Import / edit deck, Card data, Images and help. In-game tools (Active effects, Cost effects, Deck stats, Always yield, Token glossary, Dice & coin, Multiplayer) moved to a new Game tools button (the ☰ beside the gear).'] },
  { v: '0.98.2', title: 'Counterspell rules', notes: ['"Counter target spell unless its controller pays {N}" (Mana Leak, Force Spike, Spell Pierce...) now asks whether the cost was paid; it only counters if it was not (CR 608.2c).', '"If that spell is countered this way, put it into its owner\'s hand / on top of its library / exile it instead" (Remand, Memory Lapse, Dissipate) is honoured for your own spells.', '"Counter target spell if it has mana value 3 or less" checks the mana value.', '"Its controller may search their library..." (Boseiju, Path to Exile) is linked to the target and read as your own library when the permanent is yours.'] },
  { v: '0.98.1', title: 'Official token pictures from Scryfall', notes: ['Token pictures can now be downloaded the same way card pictures are: the tokens your deck can make are fetched automatically when Images auto-download is on, and the Token glossary has Download buttons for your deck\'s tokens or every token.', 'Order of art on a token: your own picture, then the official picture, then the generic art.', 'Official pictures are cached on this computer, so they keep working offline once downloaded.'] },
  { v: '0.98.0', title: 'Token art and Token glossary', notes: ['Every token now has generic art drawn by the app (colour frame, an icon for its kind, name, type and P/T), since tokens have no official art here.', 'New Token glossary & art (Tools menu, and a button in the Tokens tracker): browse every token the app knows, see how many of its abilities are implemented, and add your own picture to any token. Pictures are stored on this computer and used on the table, in the preview, in stacks and in the graveyard.', 'Generic token art can be switched off in the glossary.'] },
  { v: '0.97.7', title: 'Token abilities and tracker', notes: ['Tokens with activated abilities (Treasure, Junk, Food, Clue, Shard, Lander...) now glow green when you can activate them, like any other permanent.', 'Mana tokens work as mana sources. Powerstone\'s "can\'t be spent to cast a nonartifact spell" and "spend this mana only to..." restrictions are enforced when paying (CR 106.6).', 'New token presets: Junk, Shard, Lander, Incubator.', 'The Tokens tracker now lists each token\'s ability lines with a status mark: implemented, read as a static effect, or not implemented.'] },
  { v: '0.97.6', title: 'Linked effects: "this, then that" are one effect', notes: ['Effects whose second part depends on the first are now one unit instead of two separate buttons (CR 608.2b, 608.2c). "Destroy up to one target nonland permanent. Its controller creates a tapped Powerstone token." (Cityscape Leveler): with no target chosen nothing happens; if the target was your permanent you get the token; if it was your opponent\'s permanent they get it (your opponent\'s life changes are applied, other results are logged for you to apply at the table).', '"If you do" / "When you do": the second part happens only if the first part was actually done. If the app can do the first part it checks the game changed; if you have to do it by hand (sacrifice, behold ...) it asks "did you do it?".', '"That player ..." after a target is read the same way as "its controller".'] },
  { v: '0.97.5', title: 'Becomes-a-creature and base P/T effects', notes: ['New rules-text readers (CR 613.1d, 613.4b, 611.2): "~ becomes a 2/2 creature [with flying] until end of turn. It\'s still a land" (manlands), "target land you control becomes a 4/4 Elemental creature with haste until end of turn", "target creature has base power and toughness 1/1 until end of turn" and "until your next turn" versions now apply the new type, power/toughness and keywords and end on time (before they were only a "Remember" note).', 'The card now shows its changed type line (for example Artifact Creature / Land Creature) and its P/T, and the effects end when the permanent leaves the battlefield.'] },
  { v: '0.97.4', title: 'Glow fix, no duplicate draw, Karn the Great Creator', notes: ['Fixed: the green glow on cards with a usable activated ability was hidden by the "cards float" battlefield effect, so it never showed. Both now run together.', 'Fixed: an effect such as Kozilek\'s Command ("scries X, then draws a card") listed the draw twice ("Draw 1 card" and "You draw 1 card"), so applying both drew two cards. Each step is now listed once, in the order the text gives them, and "scries" is understood.', 'Karn, the Great Creator now works from its rules text: +1 makes up to one target noncreature artifact an artifact creature with power and toughness equal to its mana value until your next turn (it stops at the start of your next upkeep); −2 lets you put an artifact card from your sideboard or face up in exile into your hand.'] },
  { v: '0.97.3', title: 'Always yield', notes: ['New "Always yield" (like Magic Online): the first time each triggered ability goes on the stack in a game you are asked once whether to always do the same thing. Say yes and from then on it goes on the stack by itself with the same targets, applies the same effect you chose the first time, and resolves without asking (e.g. a creature that pings your opponent every time you cast a spell).', 'Manage or remove entries from ⚙ → Always yield. Everything resets when the game ends.'] },
  { v: '0.97.2', title: 'Soulbond and Reinforce', notes: ['Soulbond (CR 702.95): when a soulbond creature enters you may pair it with another unpaired creature, and when another creature enters while a soulbond creature is unpaired you may pair them. Paired creatures show a "Paired" badge, both gain the keywords or +N/+N the card\'s own "as long as this creature is paired with another creature, each of those creatures ..." line gives, and they unpair when either leaves the battlefield.', 'Reinforce (CR 702.77): right-click the card in your hand to pay the reinforce cost, discard it and put N +1/+1 counters on a target creature (the ability uses the stack).'] },
  { v: '0.97.1', title: 'Mana Drain delayed mana, interactive preview, Hand tab', notes: ['Delayed mana from rules text (CR 603.7): "At the beginning of your next precombat main phase, add an amount of {C} equal to that spell\'s mana value" (Mana Drain) is now set up when the counter resolves and adds the mana at the start of your next precombat main phase.', 'The enlarged card preview is interactive again: it only changes after the pointer rests on a card for a moment and never changes while the pointer is on it, so you can click to flip a double-faced card or hover its keyword chips.', 'The Hand / Key tab moved to the bottom right.'] },
  { v: '0.97.0', title: 'LAN multiplayer (shared table)', notes: ['New ⚙ → Multiplayer (LAN): play a friend on the same network with no server and no account. One player creates an invite code, the other pastes it and sends back a reply code (direct peer-to-peer connection).', 'You each play your own deck as usual. A docked panel shows your opponent\'s live battlefield, graveyard, exile, stack, life, hand and library SIZES, and a chat box. Hands and libraries never leave your computer.', 'Combat damage you deal and the opponent life buttons change your friend\'s real life total. This first stage is a shared table; automatic priority and targeting across players come next.'] },
  { v: '0.96.31', title: 'Chalice of the Void, Ugin −11, cleaner menus', notes: ['Chalice of the Void now works from its rules text (CR 603.2): "whenever a player casts a spell with mana value equal to the number of charge counters on it, counter that spell" triggers for the matching spell only, X spells count as X=0 on the stack, and the trigger really counters the spell.', 'Search effects that exile their finds ("search your library for any number of colorless nonland cards, exile them, then shuffle. Until end of turn, you may cast those cards without paying their mana costs", e.g. Ugin, Eye of the Storms −11) now work: you pick any number of matching cards, they are exiled, and the Exile window shows a "Cast free (this turn)" button.', 'Colors are read from rules text (CR 105.2): "colorless spell", "target permanent that\'s one or more colors" and color words in trigger filters and targets are enforced.', 'Removed the trailing "…" from the Tools menu and Settings labels.'] },
  { v: '0.96.30', title: 'Urza\'s Saga Construct, imprint with conditions', notes: ['Fixed: the 0/0 Construct token that Urza\'s Saga makes ("This token gets +1/+1 for each artifact you control") was put into the graveyard the moment it was created. "This token" is now understood as the token itself in every static ability, so the Construct counts itself and your other artifacts.','Imprint (CR 607) now reads conditions on the exiled card: "a colorless card with mana value 7 or greater" (Ugin\'s Labyrinth), and "If a card is exiled with this land, add {C}{C} instead" makes the land tap for two.'] },
  { v: '0.96.29', title: 'Tron checks land types, not names', notes: ['"If you control an Urza\'s Mine and an Urza\'s Power-Plant" is now checked the way the rules define it (CR 205.3i): Urza\'s Mine, Urza\'s Power-Plant and Urza\'s Tower are land types, so the app looks at each permanent\'s type line and never at what the card is called. Any land with those types counts.'] },
  { v: '0.96.28', title: 'Lands stay on one row when they fit', notes: ['A row of lands (or artifacts) no longer wraps to a second row while there is room: the zone now measures the real width of its cards (a tapped land is turned sideways and a stack of copies is wider) instead of assuming every card is the same width. Cards still shrink only when they truly cannot fit.'] },
  { v: '0.96.27', title: 'Tron lands fixed', notes: ['Urza\'s Mine, Power Plant and Tower now tap for their full amounts in any order. The cause: the card is named "Urza\'s Power Plant" but the Oracle text of the Mine and Tower says "Urza\'s Power-Plant", so they never found it. Names are now compared without punctuation.'] },
  { v: '0.96.26', title: 'Opening-hand reveals, global rules from your deck report', notes: ['Devourer of Destiny and every card worded "You may reveal this card from your opening hand. If you do, at the beginning of your first upkeep, ...": the pre-game screen now has a Reveal button, and the effect goes on the stack at your first upkeep (Devourer: look at the top four, keep one on top, exile the rest).','Ensnaring Bridge: creatures with power greater than the number of cards in your hand can\'t attack (the attack list updates live as your hand changes).','Torpor Orb: creatures entering no longer cause abilities to trigger. Grafdigger\'s Cage: creature cards can\'t enter the battlefield from a graveyard or library, and spells can\'t be cast from graveyards. Omnath: unspent mana becomes colorless instead of emptying. Damping Sphere: each spell costs {1} more for each other spell cast this turn. "Lands you control enter untapped" is applied.','Vesuva and similar lands are recognised in the current Oracle wording. The card-reading report counts all of these as understood.'] },
  { v: '0.96.25', title: 'Token doubling, honest card report, Serum Powder only when usable', notes: ['The opening-hand screen only shows the Serum Powder button when a card in your hand allows it (CR 103.5b); it is no longer shown greyed out all the time.','Token-creation replacement effects (CR 614): "If an effect would create one or more tokens under your control, it creates twice that many instead" (Doubling Season, Parallel Lives, Anointed Procession) and "that many plus N" are read from the rules text and applied whenever an effect creates tokens. Doubling Season only doubled counters before.','The card-reading report (How the app reads your deck) now counts everything the engine really handles: it picks up keywords with triggers, effects, alternative costs or a rules test by itself, plus Warp/Flashback lines, "cast from your graveyard" lines, token replacement lines and Reanimate-style life loss. On the sample deck, lines the report did not understand went from 7 to 0.'] },
  { v: '0.96.24', title: 'Green glow, popups above the hand, rules-driven statics', notes: ['Permanents and planeswalkers with an ability you can activate right now get a soft pulsing green glow; when nothing can be activated there is no glow.','The stack and the resolving prompt (including its Discard / Resolve buttons) now sit in the space above your hand, so the hand can no longer cover them.','Kaito, Bane of Nightmares: during your turn, while he has loyalty counters, he is now a 3/4 Ninja creature with hexproof (type, power/toughness, creature row and keyword). This is read from the words of the static ability, not from his name, so every card with that wording works.','New general reader for a permanent\'s own statics: "As long as [condition], ~ is a N/N [types] creature with [keywords]", "~ has [keyword] as long as [condition]" (Bloodghast) and "~ can\'t block" (Gravecrawler, Bloodghast). The card-reading report now counts these as understood.'] },
  { v: '0.96.23', title: 'Zones resize to fit, keyword batch 7', notes: ['Every battlefield zone now measures its cards after layout and shrinks them in real time until all of them fit, so a fourth or fifth land no longer wraps under the zone or gets clipped.','Hideaway N (702.75): when it enters, look at the top N cards, exile one face down, put the rest on the bottom in a random order; right-click the permanent and choose Hideaway to play the exiled card free (a land is put onto the battlefield).','Undaunted (702.125): costs {1} less for the opponent. Encore (702.141): from your graveyard at sorcery speed, exile the card to create a hasty token copy that is sacrificed at the next end step.'] },
  { v: '0.96.22', title: 'Keyword batch 6, Welcome tour updated', notes: ['Squad (702.157): pay the squad cost any number of times as you cast it; when it enters you create that many token copies. Offspring (702.175): an optional extra cost; if paid, a 1/1 token copy when it enters.','Impending (702.176): cast for the impending cost, it enters with N time counters, is not a creature while it has one, and loses one at the beginning of your end step.','The Welcome tour now describes the current app: the turn-flow bar, one-click sets, the new songs, Dice & coin, the Next round screen, the real Settings tabs and the Hand Key.'] },
  { v: '0.96.21', title: 'Next round screen, dice and coin, bar opacity', notes: ['When a game ends (opponent at 0 life, or you lose at 0 life, ten poison counters or an empty library) a Victory / Defeat screen appears with Next round (same deck), Sideboard then play, Choose another deck, or Keep playing. It also keeps a win/loss count for the session.','Coin flips and die rolls now tumble on screen and land on the real result: a 3D coin that stops on heads or tails, and dice (a real cube for d6, shaped dice for d4 to d100). The result is picked first with a true random number and the animation lands exactly on it. "Flip a coin" and "Roll a d20" in card text use it, and there is a new Dice & coin tool in the tools menu. Turn it off with Dice & coin tumble in the animation list.','New Turn-flow bar opacity slider (Settings > Look).','Settings: the panel could be taller than the space above your hand, so the last options could not be scrolled into view. It now fits the free space.'] },
  { v: '0.96.20', title: 'Battlefield flicker fix', notes: ['Fixed the flicker with five or more permanents in a zone: a card kept hopping between sitting in the row and wrapping underneath. The zones no longer show a scrollbar (it appeared and disappeared, changing how many cards fit), the number of columns is now set exactly from the card size so the browser cannot round it differently from frame to frame, and the fit keeps a few pixels of margin. Zones still scroll with the mouse wheel.'] },
  { v: '0.96.19', title: 'Targeting fix: "an opponent controls"', notes: ['Spells and abilities that say "target nonland permanent an opponent controls" (Leyline Binding, Banishing Light-style cards) or "target creature an opponent controls" no longer offer You and Opponent as targets. Only permanents are legal targets there (CR 115.2); because the opponent\'s board is not tracked, the single "a permanent your opponent controls" choice remains.'] },
  { v: '0.96.18', title: 'Steady, filling turn bar; one-click sets; more music', notes: ['The turn-flow bar is now always the same size and its steps never shift: the button slot is fixed, the stack count floats, and the current step no longer gets wider. It also fills like a loading bar up to the step you are in, in your theme colours.','One-click sets now exist for every interface theme (Midnight, Obsidian & gold, Abyss blue, Forest, Neon, Parchment, Light, Pixel cosmos): the theme, card sleeve, playmat, board frame and a matching song all change together (Settings > Look). Untick Matching music to leave your song alone.','Five new generated songs (Settings > Sound > Music style): Dusty boom-bap, Rainy window, Midnight jazz-hop, Arcade chill and Golden hour, next to Cosmic low-fi.','Frenzy (702.68): +N/+0 when it attacks unblocked. Scavenge (702.97): exile it from the graveyard for +1/+1 counters equal to its power on a creature.'] },
  { v: '0.96.17', title: 'Keyword batch 5', notes: ['Exploit (702.110): when it enters you may sacrifice a creature (it can sacrifice itself); "when this creature exploits a creature" then triggers.','Enlist (702.154): as it attacks, tap an untapped nonattacking creature that is not summoning sick; it gets +X/+0 for that creature\'s power.','Mobilize N (702.181): N tapped and attacking 1/1 red Warrior tokens, sacrificed at the next end step; they do not trigger attack abilities.','Unleash (702.98): optional +1/+1 counter, and the creature cannot be assigned as a blocker while it has one (decayed now also blocks that way).','Devour N (702.82): sacrifice any number of creatures for N counters each. Ravenous (702.156): X counters, draw a card if X is 5 or more.','Fixed: Bolster with tied creatures now actually puts the counters on the creature you pick.'] },
  { v: '0.96.16', title: 'Smoother play, fixed turn-flow bar', notes: ['The turn-flow bar now sits in its own row between the battlefield and the lower zones, so it no longer moves when the combat notice appears. The pre-game actions panel now sits above the floating hand. Drawing and re-rendering are much lighter (layout runs once per frame, repeated rules lookups are cached), and the GPU is used for rasterising for a higher frame rate.'] },
  { v: '0.96.15', title: 'Rules-check panel, no Draw 7', notes: ['The opening-hand screen no longer has a Draw 7 button. The rules-check pop-up for discarding to hand size now uses the same panel style as other pop-ups instead of a blank card.'] },
  { v: '0.96.14', title: 'Pop-ups stay above your hand', notes: ['The glowing outline is back on hand cards: green glow for playable now (gently pulsing), red for not enough mana, amber for wrong timing.', 'Centred pop-ups (pre-game actions, choices, search windows) now sit in the space above your hand, so the hand no longer covers their buttons.'] },
  { v: '0.96.13', title: 'Release set fixed, movable Hand label', notes: ['Updater: releases now always come with a SIXTH file, update.json, which older app shells read (its absence caused "update.json has no version"). The release script bundles all six files into one zip and the update window names the missing file.','The small Hand label (count and Key) can be dragged anywhere on the table; its place is remembered and double-clicking puts it back. The Sort button is gone: drag cards sideways in the hand to order them.'] },
  { v: '0.96.12', title: 'Tezzeret, Cruel Captain in full, emblems', notes: ['Tezzeret, Cruel Captain now follows his real Oracle text: "Whenever an artifact you control enters" adds a loyalty counter; 0: untap target artifact or creature and, if it is an artifact creature, put a +1/+1 counter on it; \u22123: search for an artifact card with mana value 1 or less, reveal it, put it into your hand, shuffle; \u22127: you get an emblem.','Emblems (CR 114) are new: "You get an emblem with \u2026" creates a permanent emblem that lives outside the battlefield, shown in a small panel on the mat, and its abilities trigger like any other (Tezzeret\'s emblem puts three +1/+1 counters on a target artifact at the beginning of combat and turns a non-creature one into a 0/0 Robot artifact creature).','Effects that make a permanent a creature (CR 613.1d, 613.4b) now change its types, subtypes and base power/toughness, so it moves to the creature row and counts as a creature everywhere.','"Put a +1/+1 counter on it" after a target no longer puts the counter on the ability\'s source. Mana value for searches is now worked out from the mana cost (CR 202.3).'] },
  { v: '0.96.11', title: 'Battlefield never hides behind the hand', notes: ['The hand now overlaps only the very bottom edge of the playmat. The mat reserves the rest, so second rows of artifacts, enchantments and lands are no longer covered, and cards shrink further (down to about a third of full size) on crowded boards so every card stays visible.', 'The battlefield re-fits itself whenever a zone or the hand changes size (resizing, drawing, playing cards).'] },
  { v: '0.96.10', title: 'Ordered effects, safer static abilities', notes: ['"A, then B" effects (The One Ring) now list their steps in written order (CR 608.2c) and no longer show a combined "In order" choice; the ordering stays internal.', 'Static abilities (CR 604, 613): "gets +1/+1 for each artifact you control" now counts permanents by their current types, tokens included, and a "for each" the app cannot read is treated as unknown instead of 0, so state-based actions (CR 704.5f) no longer destroy a creature such as the Urza\'s Saga Construct because of a failed count.'] },
  { v: '0.96.9', title: 'Keyword batch 4, floating hand', notes: ['Hand: the cards now hover gently, each at its own pace, with a soft shadow that deepens as a card lifts. It pauses on hover and can be switched off in the animations list (Floating hand), and it respects the reduced-motion setting.','Decayed (702.147): when it attacks, a delayed \"sacrifice at end of combat\" is set up; end-of-combat delayed effects now exist.','Exert (701.43): \"You may exert it as it attacks\" asks on attack; an exerted permanent stays tapped through your next untap step; the linked \"when you do\" ability is put on the stack.','Monstrosity N (701.37): counters and the monstrous marker, only if it is not already monstrous; \"becomes monstrous\" triggers now work; the marker ends when it leaves the battlefield.','Populate (701.36): choose a creature token you control and create a copy of it; with none, nothing happens.','Boast (702.142): the ability is only usable if the creature attacked this turn, and once each turn. Devoid (702.114): always colorless.','Six new CR-numbered tests: 73 of 73 rules checks pass.'] },
  { v: '0.96.8', title: 'Updater fix, floating hand', notes: ['Updater: the in-app updater downloads every file from the newest GitHub release, so a release that only carried the changed files made the update fail with a 404. Releases should carry all five files (index.html, app.js, style.css, package.json, latest.json), and the updater now also reuses any file whose checksum already matches the installed copy, so partial releases work too (this part needs the new app shell: reinstall the full package once).','Updater: no-cache requests and time-outs, clear messages when the release is missing a file, is a draft or pre-release, or has no latest.json.','Hand: no more hand box. Your cards float along the bottom of the screen over the battlefield, always fully visible. The battlefield keeps its bottom edge clear so permanents are not hidden.','The colour key (Playable / Can\'t pay / Wrong timing / Instant speed / Selected) moved behind a small Key button next to Sort, so it no longer sits permanently in the hand area.'] },
  { v: '0.96.7', title: 'Upkeep keywords: Cumulative upkeep, Vanishing, Fading', notes: ['Cumulative upkeep (702.24): at your upkeep an age counter goes on the permanent, then you may pay the cost once for each age counter, or sacrifice it. Mana costs open the normal payment window; \"Pay N life\" is taken for you; any other cost (sacrifice, discard...) is marked as paid by hand. When the cost has choices (\"{W} or {U}\"), every combination across the age counters is offered, and a partial payment is never possible.','Vanishing N (702.63): enters with N time counters; at your upkeep, only if it has one, a time counter is removed; removing the last one puts a \"sacrifice it\" trigger on the stack.','Fading N (702.32): enters with N fade counters; at your upkeep a fade counter is removed, and if it has none the permanent is sacrificed.','Keyword lines are now read with their whole argument (a number, a mana cost, or a full cost such as \"Cumulative upkeep\u2014Pay 1 life\"), and upkeep keyword abilities respect their \"if\" condition.','Four new CR-numbered tests: 67 of 67 rules checks pass.'] },
  { v: '0.96.6', title: 'Phyrexian & hybrid mana, Ancient Tomb, bigger battlefield', notes: ['Ancient Tomb and every land like it: the damage sentence was only recognised when it used the card\'s printed name, but current Oracle text says \"this land deals 2 damage to you\". Mana abilities now read every sentence of the line, with the card\'s name or \"this land / artifact / creature\" alike. The two mana and the 2 damage now happen together. \"You lose N life\" is read too, and any sentence the app does not understand is listed in the card report as NOT applied instead of being skipped silently.','Phyrexian mana (CR 107.4f) is now read and paid: coloured mana if you have it, otherwise 2 life per symbol (only if your life total allows it), with a log line. Hybrid ({W/U}) and two-brid ({2/W}) symbols now need one of their colours (or two generic) instead of any mana (107.4e). The symbol shows as W/P, W/U, 2/W.','The self-name reader now handles \"this land\", \"this artifact\" etc. in more places (land abilities, enters-with-counters, state triggers).','Layout: the hand box is shorter and the hand overlaps the bottom edge of the battlefield, so the battlefield is about 40 pixels taller. Hovered cards still rise over everything.','Three new CR-numbered tests (107.4f, 107.4e, 605.1a): 63 of 63 rules checks pass.'] },
  { v: '0.96.5', title: 'Recursion keywords: Embalm, Eternalize, Unearth, Outlast, Rebound, Disturb', notes: ['Embalm (702.128) and Eternalize (702.129): open your graveyard and press the keyword button on the card. You pay the cost, the card is exiled as part of it, and you get a token copy: white for Embalm, black and 4/4 for Eternalize, a Zombie in addition to its other types, with no mana cost. Sorcery speed only.','Unearth (702.84): the card returns from the graveyard with haste, is exiled at the beginning of the next end step, and is exiled instead if it would leave the battlefield. Sorcery speed only.','Outlast (702.107) now shows as an ability: {cost}, {T}: put a +1/+1 counter on it, sorcery speed only.','Rebound (702.88): a spell cast from your hand is exiled instead of going to the graveyard as it resolves, and at your next upkeep a prompt lets you cast it from exile without paying its mana cost (a spell cast from anywhere else, or a copy, does not rebound).','Disturb (702.146): a double-faced card with disturb gets a Disturb button in the graveyard; the back face goes on the stack, enters back face up, and is exiled if it would go to a graveyard.','Also in this release: the broad name-check sweep found no remaining card-name checks. The fetch, shock and basic-land name lists are now used only when card data is not loaded.','Six new CR-numbered tests: 60 of 60 rules checks pass.'] },
  { v: '0.96.4', title: 'Rules-text audit: no more name checks', notes: ['Serum Powder is now found by its rules text (CR 103.5b: \"any time you could mulligan and ~ is in your hand, you may exile all the cards from your hand, then draw that many cards\"), not by its name. Any card with that wording gets the same button.','Leyline-style cards are found by CR 103.6a wording (\"if ~ is in your opening hand, you may begin the game with it on the battlefield\") instead of looking for the word Leyline. Cards that only let you reveal from your opening hand (CR 103.6b) are no longer offered a battlefield button.','Vesuva-style lands (\"enter the battlefield tapped as a copy of any land\", CR 614.12) are recognised by text. Leyline of the Guildpact, Dryad of the Ilysian Grove, Prismatic Omen, Urborg, Yavimaya, Blood Moon and Magus of the Moon are now read only from what they say (CR 305.7).','Hand-written card definitions are now one flat list matched by rules wording, never by card name, so a new card with the same text behaves the same. Two definitions that only repeated the general reader (Mana Crypt, Necrodominance) were removed, and a second Wan Shi Tong line no longer overwrites the first.','Five new CR-numbered tests (103.6a, 103.5b, 614.12, 305.7, 112.1) using invented card names with real rules text: 54 of 54 rules checks pass.'] },
  { v: '0.96.3', title: 'Keywords batch 3: the harder casting keywords', notes: ['Overload (702.96) and Bestow (702.103) are chosen BEFORE targets, as the rules say (601.2b): a small window asks how you want to cast it. Overload turns every "target" in the spell into "each", so no targets are chosen and the effect window reads "each". Bestow asks for a creature, resolves attached to it (its "Enchanted creature gets..." bonus applies) and, if the host leaves, stays as a creature.','Escalate (702.120): each mode chosen beyond the first adds the escalate cost, shown in the total. Replicate (702.56): the cost window has a number box, pay it any number of times, and the spell is copied that many times.','Emerge (702.119): sacrifice a creature and the cost is reduced by its mana value; the route is only offered when your best sacrifice makes it payable. Prowl (702.76): needs combat damage dealt this turn by a creature sharing a creature type with the card.','Miracle (702.94): the first card you draw each turn that has miracle triggers a window to cast it for the miracle cost. Plot (702.170) and Foretell (702.143): right-click the card in hand to pay and exile it; later turns the Exile list offers Cast free (plotted) or Cast (foretold, for the foretell cost).','Cast-window fix: a spell with an optional extra cost other than kicker (casualty, replicate) is no longer logged as "kicked".','Nine more rules checks (49 now), each named after its rule number.','Not exact yet: overloaded spells whose "each" effect the app cannot do for you are applied by hand; a foretold card is not hidden face down; miracle clears when you close its window, so cast it right away; a bestowed card is drawn with the creatures while attached; Escalate with a non-mana cost (discard a card) is not read.'] },
  { v: '0.96.2', title: 'Keywords batch 2: alternative casting costs', notes: ['Blitz (702.152): cast for the blitz cost, the creature has haste, is sacrificed at the beginning of the next end step, and draws you a card when it dies. Dash (702.109): haste, and it returns to your hand at the next end step.','Spectacle (702.137) can only be used if an opponent lost life this turn; Surge (702.117) only if you have cast another spell this turn. When the condition is not met the cost window says why instead of letting you pay.','Casualty N (702.153): an optional extra cost, sacrifice a creature with power N or greater; if you pay it the spell is copied, like storm.','Cost lists understand "a creature with power N or greater" for any card that asks for it.','Five more rules checks (40 now), each named after its rule number.','Still to do: Emerge, Bestow, Overload, Replicate, Escalate, Prowl, Miracle and Plot.'] },
  { v: '0.96.1', title: 'Keywords batch 1: triggers and keyword actions', notes: ['Triggered keywords are now built from one table and follow their Comprehensive Rules wording: Exalted (702.83, only when a creature attacks alone), Battle cry (702.91), Annihilator N (702.86), Evolve (702.100, only when the entering creature has greater power or toughness), Renown N (702.112, once), Mentor (702.134, only a creature with lesser power), Training (702.149, only with a creature of greater power), Dethrone (702.104), Melee (702.121), Fabricate N (702.123: counters or Servo tokens), Modular N (702.43: enters with the counters, dies trigger), Bloodthirst N (702.54), Riot (702.136) and Extort (702.101).','Keyword actions inside card text: Bolster N (701.39, least toughness, you choose among ties), Adapt N (701.46, only if it has no +1/+1 counters), Connive (701.50, draw, discard, counter if the discard was a nonland card) and Discover N (701.57, cast free or put in hand, rest to the bottom).','Each keyword has a rules test named after its CR number (35 rules checks now).','Not exact yet: Bloodthirst and Riot are replacement effects ("as it enters") but are offered as an enters-the-battlefield window; Annihilator and Extort cannot touch your opponent because the goldfish opponent has no board. Extort asks you to tap the mana yourself.'] },
  { v: '0.96.0', title: 'Legal notice, rules table, source split', notes: ['New Settings > Legal notice tab: the fan-content notice, what is and is not included (no card images, artwork or card database), where card data comes from, privacy, no-warranty and third-party software. The same text is in the README.','Scryfall requests from the desktop app now send a descriptive User-Agent and an Accept header, as Scryfall asks (needs the full package installed once).','The Comprehensive Rules (6 Nov 2026) are now a table inside the app: every keyword action and keyword ability, its rule number and how far the app has got (tested, named, never mentioned). The Scan every card tool shows the rule number and status next to each keyword the app only explains, ranked by how many cards use it.','The app code is now split into 40 source files in src/ and joined into app.js by node build-src.js. app.js is exactly the same program as before, so nothing changes for players.','Ninjutsu and flashback no longer show in the scan as "only explained".'] },
  { v: '0.95.3', title: '"For each" understood: The One Ring', notes: ['The One Ring: the upkeep trigger now loses 1 life for each burden counter, and the tap ability puts a burden counter on it and then draws a card for each burden counter (counted after the new counter is added). Before, both were read as a flat 1.','New shared quantity reader: "for each X" and "equal to the number of X" now count counters on the source (burden, +1/+1, any kind) as well as everything the app already counted, and the amount is worked out at the moment the effect happens, not when the window opens. Used for draw, lose life and gain life.','"Do A, then do B" inside one sentence is now offered as an ordered chain, like "Do A. Then do B."','If the app cannot count a "for each" phrase it says so and asks you to do it by hand, instead of silently using 1.'] },
  { v: '0.95.2', title: 'Jewel Shops pass: Mox Opal, Chrome Mox, Workshop', notes: ['Mox Opal now works. Its "Metalcraft \u2014 {T}: Add one mana of any color" line started with an ability word, so the app never read it as a mana ability at all. Any "Word \u2014 {T}: Add ..." mana line is now understood.','Metalcraft-style limits ("Activate only if you control three or more artifacts") are now checked: with fewer artifacts Mox Opal is not offered for payment, with three it is. Works for any "N or more <type>" limit.','Chrome Mox imprint: its enters-the-battlefield ability lets you pick a nonartifact, nonland card from your hand to exile; the Mox then taps for the colours of that card (none if you skip it or the card is colourless). Any card that says "you may exile a ... card from your hand" with Imprint is handled the same way.','Mishra\'s Workshop and other "spend this mana only to cast ..." lands: the cast check now includes the spell, so artifact spells show as castable with Workshop mana.','Not automated yet (still by hand): Grim Monolith\'s {4}: Untap, Mana Drain\'s delayed colourless mana.'] },
  { v: '0.95.1', title: 'UI polish', notes: ['Piled-up lands no longer show a second card name peeking through the top card.','Zone labels (Artifacts · Enchantments · Planeswalkers) are cut with an ellipsis instead of running over the cards in narrow windows; the Images / Card data chips do the same.','Tokens: the Token tray no longer lists a made-up "or more" token from Doubling Season-style wording.','Sound settings: the Low-fi drums switch only shows when the Cosmic low-fi style is chosen. The Cosmic low-fi label in Look & feel no longer wraps. Token tray rows have a little room under the intro.'] },
  { v: '0.95.0', title: 'Tokens are real cards; Urza\'s Saga; loyalty counters', notes: ['Tokens now behave like cards: their rules text is read for static abilities, triggers and activated abilities. Before, a token\'s own text was ignored, so the Construct from Urza\'s Saga ("This creature gets +1/+1 for each artifact you control") entered as 0/0 and died at once. It now counts itself and the other artifacts and lives (a lone Construct is 1/1).','New: official token data. When you load the Scryfall card file the app now also keeps its token cards (type, rules text, power/toughness, colours). When a card says it creates a token, the matching official token supplies the real type line and text. Load your card file (or use the download button) once again to fill this in; Settings → Card data shows how many tokens are loaded.','"~ gets +1/+1 for each …" works for any card, on itself or on others, not only mana-count cards. Counting "artifacts you control" now counts tokens by what they are.','Tezzeret, Cruel Captain and anything else that says "put a loyalty counter": the counter now changes the planeswalker\'s loyalty instead of creating a separate "loyalty" counter.','Urza\'s Saga was checked end to end: chapter I gives the mana ability, chapter II gives the Construct ability, chapter III searches for an artifact with mana value 0 or 1, and the Saga is sacrificed after it resolves.'] },
  { v: '0.94.7', title: 'Ninjutsu, one update window, tidy-up pass', notes: ['Ninjutsu works: right-click a card with ninjutsu in your hand after blockers are declared (declare blockers step up to end of combat). You pick an unblocked attacker to return to hand, pay the ninjutsu cost, and the ability goes on the stack; when it resolves the card enters tapped and attacking (it was not declared, so "whenever this attacks" does not trigger). The menu says why it is not available when it is not.','One update window: the start-up notice and the Update app menu entry are now the same window. It checks GitHub when you open it, shows what changed, has the progress bar, and puts folder / web-address / go-back-to-built-in under "Other ways to update". The two check-at-start settings sit in it as two plain checkboxes.','The same suggestion is never listed twice in an effect window (a safety net on top of the Prismari Command fix).','Declare attackers: Attack with all and Clear now sit in the same column as the creature list and are not highlighted, so Declare attackers is the one main button.'] },
  { v: '0.94.6', title: 'Sink into Stupor // Soporific Springs (modal double-faced cards)', notes: ['The land side now works as its own card: Soporific Springs asks "pay 3 life or enter tapped" when you play it from the card (it entered untapped with no question before). Any land that says "you may pay N life. If you don\'t, it enters tapped" is understood, not just 2-life shocklands.','The spell side now works too: Sink into Stupor could not be cast because "target spell or nonland permanent an opponent controls" was read as a spell only. It now accepts a spell on the stack or a permanent, and "an opponent controls" is respected.','Returning a spell to its owner\'s hand takes it off the stack (an opponent spell you added to the Stack box just leaves it).'] },
  { v: '0.94.5', title: 'One draw option, and targets say which mode they are for', notes: ['Fixed: cards that say "target player draws…" (Prismari Command and similar) showed the draw twice, once tied to its target and once as a loose copy, so you could apply it twice. Only the targeted one is offered now.','The target window now shows a "For: …" line under each target heading with the sentence it belongs to, so on a "choose two" card you can see which chosen mode each target is for.'] },
  { v: '0.94.4', title: 'Vengevine and Cabal Therapist', notes: ['Vengevine: "if it\'s the second creature spell you cast this turn" is now checked (rule 603.4). The trigger only appears on your second creature spell of the turn (noncreature spells in between do not count), and it returns Vengevine itself, nothing else. The same check works for "first/second/third spell" and typed versions on other cards.','Fixed a crash when applying "return ~ from your graveyard" suggestions (Vengevine, Bloodghast): the button threw an error and nothing returned.','Cabal Therapist: the whole chain (target, sacrifice, resolve, choose a nonland card, discard) was re-tested from start to finish, including sacrificing Therapist itself, and works in my tests. If it still fails for you, tell me which target you chose and what you saw.'] },
  { v: '0.94.3', title: 'Attack with all, counter chips, sleeve fix', notes: ['Declare attackers has an "Attack with all" button. It selects every creature that can legally attack (not tapped, not summoning sick unless it has haste, no defender, no "can\'t attack" effect) and lists the ones it left out and why. Clear undoes it, and you can still toggle single creatures before declaring.','Counters are now chips on the card: a green "5 +1/+1" instead of "+1 5", red for −1/−1, blue for other kinds (hover for the full sentence).','Fixed: your chosen card sleeve looked reset every time the app started (only uploaded images were re-applied). Presets are applied at start-up now.','The 1-2-3 step strip is hidden when the centre shows a discard or card choice.'] },
  { v: '0.94.2', title: 'Discards and card choices in the centre', notes: ['When you must discard or choose cards from your hand, the choice now appears in the middle of the table next to the card that causes it: the spell or ability being resolved, the card whose cost you are paying, or the hand-size rule at cleanup. Previously only some ability-driven discards did.','Select the cards in your hand as before; the count, note and Discard button are in the centre. Anything waiting on the stack is mentioned.','New switch in Settings > Board: "Discard and card choices in the centre". Off brings back the thin bar above your hand. The mulligan bottom step is unchanged.'] },
  { v: '0.94.1', title: 'Warp, true-shape piles, music switch', notes: ['Warp (Timeline Culler and friends): cast for the warp cost from your hand, it is exiled at the beginning of the next end step, and from a later turn you can cast it from exile for its normal cost (Cast button in the Exile window). Timeline Culler can also be cast with warp from the graveyard.','Library, graveyard and exile piles keep a true card shape (5:7) at every window size instead of being cropped or stretched, and sit evenly spaced.','The Cosmic low-fi music switch next to Apply Pixel cosmos set is now the same setting as Settings > Sound > Music style, so it no longer switches itself off when Settings closes.','Returning from the graveyard: Bloodghast-style "return this from your graveyard" landfall triggers now fire from the graveyard; Gravecrawler can be cast from the graveyard while you control a Zombie; "Return all" / "at random" / "mana value N or less" / "tapped" wordings and Reanimate ("Put target creature card from a graveyard onto the battlefield under your control. You lose life equal to its mana value.") now work.'] },
  { v: '0.94.0', title: 'Update window with a progress bar', notes: ['When the desktop app starts and a newer version is on GitHub, an Update window opens with what changed and an Update now button. Later hides it for this run; Skip this version hides it until the next release.','Updating shows a progress bar with the file name and megabytes downloaded, then a verification step (each file is checked against its published SHA-256) and a Restart now button. Nothing is installed if a check fails.','The same progress bar is in Menu > Update app. A new switch there turns the start-up window back into the small notice.','The progress numbers need the updated app shell (shown after you install the full package once); on the older shell the bar just animates while it downloads.'] },
  { v: '0.93.2', title: 'Pixel cosmos set', notes: ['New matching set in lo-fi pixel style: the sleeve (Settings > Look & feel), the playmat (Settings > Board) and a UI theme, all called "Pixel cosmos (lo-fi)". Dusky indigo and purple with teal and pink accents, drawn on a chunky pixel grid: stars, a crescent moon and a ringed planet.','Pick each one separately, or use the one-click "Apply Pixel cosmos set" button in Settings > Look & feel to set the sleeve, mat and theme together (with an option to add the Cosmic low-fi music).','The art is an original design made for this app.'] },
  { v: '0.93.1', title: 'Cosmic low-fi music', notes: ['New music style in Settings > Sound: Cosmic low-fi. A generated, never-ending loop with a swung soft beat, warm electric-piano chords (7ths and 9ths), a soft bass, tape wobble, vinyl crackle and shimmering high notes with a long reverb.', 'Low-fi drums have their own switch. The calm ambient loop is still the default and you can switch styles while the game is running.', 'Everything is made on the fly, no audio files, works offline.'] },
  { v: '0.93.0', title: 'Linked clauses for any card', notes: ['When an effect reads "Do A. Then do B." or "Do A. If you do, B." and the app understands each part, you get one button that runs them in order.', 'An "If you do" part only runs if the step before it changed something (cards moved, life, mana); otherwise it is skipped and the log says so.', 'If a step opens its own window (a hand pick, scry), the chain waits until you finish it before judging the next step.'] },
  { v: '0.92.2', title: 'Consistency pass', notes: ['Pop-ups and Settings now use one control height (34px), one corner radius (10px) and one text size (13px): close buttons, search box, selects, number boxes, upload buttons, colour swatches and tiles.', 'Stack box: the "Opponent casts" name field now has its own row, with the type picker and Add on the next row, all the same height; View top 10 matches.', 'Hand legend chips use the same corner radius as the buttons.'] },
  { v: '0.92.1', title: 'Cabal Therapist and Duress-style discard', notes: ['"Target player reveals their hand. You choose a nonland card from it. That player discards that card." is now understood. Targeting yourself (the Reanimator use) lets you pick a nonland card from your own hand to discard; targeting the opponent is logged, since a goldfish opponent has no hand.'] },
  { v: '0.92.0', title: 'Replacement effects: you choose the order', notes: ['Counter-replacement cards (Hardened Scales, Doubling Season, Winding Constrictor and similar) now follow rule 616.1: when two or more apply to the same event, you choose the order. If the order cannot change the result, nothing is asked. If it can, the app applies the order that gives you the most counters, tells you, and offers the other order in a side window; your choice is remembered for that pair of cards.', 'The log says which effects applied and in what order.'] },
  { v: '0.91.4', title: 'Rules test suite', notes: ['New tests folder with 14 checks that play a mock game and compare the app with the Comprehensive Rules (June 2026 edition): floating mana, the stack order, spells staying on the stack until their effect is done, Storm, copies, split second, sorcery timing, toughness 0, the legend rule, the opening draw, cleanup discards and the two loss conditions. All 14 pass.', 'Corrected rule numbers I had written in notes: floating mana empties under rule 106.4 and a spell goes to the graveyard last under rule 608.2n.'] },
  { v: '0.91.3', title: 'New targets for copies', notes: ['When a spell with targets is copied (Storm, or the Copy button), a window asks for the new target of each copy in turn. Close it to keep the original\'s target (rule 707.10c).'] },
  { v: '0.91.2', title: 'Stack order list and split second', notes: ['When more than one thing is on the stack, a list under the cards shows the order: what resolves first, then the next ones, each labelled spell, copy, triggered ability, activated ability or loyalty ability.', 'Split second works (rule 702.61): while a spell with split second is on the stack you cannot cast spells or activate non-mana abilities (including loyalty abilities), the cards stop showing as playable, and a red notice explains why. You can still tap lands for mana.'] },
  { v: '0.91.1', title: 'Clearer stack and resolution', notes: ['The middle of the table now shows a three-step strip: 1 On the stack, 2 Resolving, 3 Done.', 'While an ability resolves, its card stays zoomed on the left and the "what does it do" window sits beside it instead of covering it. A short "What the app did" list under the card shows each thing the app just did (drew, discarded, added counters…).', 'Activated, triggered and loyalty abilities are labelled as such. A Finish button closes the resolution if you applied it by hand.'] },
  { v: '0.91.0', title: 'Storm and copying spells', notes: ['Storm now works: casting a spell with storm puts a Storm trigger on the stack above it, and when that resolves the spell is copied once for each spell cast before it this turn (your opponent\'s spells count too, as you enter them).', 'Copies are not cast (they do not add to the Storm count), resolve like the original, then cease to exist instead of going to the graveyard.', 'New Copy button next to Resolve top for Twincast, Fork, Reverberate and similar: it puts one copy of the top instant or sorcery on the stack. Choose new targets for copies by hand.'] },
  { v: '0.90.11', title: 'Spells stay on the stack while resolving', notes: ['Instants and sorceries now stay in the middle of the table while their effect is applied (including any discard you have to choose), and only then go to the graveyard, as rule 608.2n says. A "Finish: to graveyard" button is there if you apply the effect by hand. A setting (Board > layout) turns this off.'] },
  { v: '0.90.10', title: 'Same sizes in panels and pop-ups', notes: ['The side panels (Stack, Game log), the hand header (Sort and the legend chips) and the pop-up footers now use the same control sizes as the top bar: 34px buttons and fields in panels and pop-ups, 30px in the hand header and log link, 24px legend chips.'] },
  { v: '0.90.9', title: 'Omnath, Locus of Mana', notes: ['Omnath, Locus of Mana now works: green mana stays in your pool as steps and phases end, and Omnath gets +1/+0 for each green mana in your pool. Upwelling-style cards (mana pools do not empty) keep all mana. The log says when mana stayed.'] },
  { v: '0.90.8', title: 'Status icons fit their box', notes: ['The little status icons in the game bar were being stretched to button size by the new uniform sizing and spilled out of their box. They are back to 22px and sit fully inside it.'] },
  { v: '0.90.7', title: 'Mulligan bottom pick in your hand', notes: ['Choosing the cards to put on the bottom after a mulligan now works like discarding: the prompt, count and Confirm button sit in the bar above your hand and you click the cards in your hand. The big pop-up is gone.', 'The Next phase / Next turn buttons no longer appear above the table before a game starts (they live in the centre bar).'] },
  { v: '0.90.6', title: 'One size for controls', notes: ['Top bar controls are all 34px tall (icon buttons are 34px squares, the status chips and version badge match), and every box in the game bar (Turn, Mana, status icons, Opp, Life) is the same 44px height with 30px buttons inside, so rows line up. The status icons are a little smaller so they fit in the same height, which also gives the battlefield a bit more room.'] },
  { v: '0.90.5', title: 'Ability stays in the centre while you choose', notes: ['When a triggered or activated ability asks you to discard (Territorial Kavu, Faithless Looting and similar), the card it comes from now stays zoomed in the middle of the table with its ability text, along with the prompt, the count and the Discard button. You still click the cards to discard in your hand.'] },
  { v: '0.90.4', title: 'Centre bar never overlaps', notes: ['When Declare attackers appears, the centre bar now shrinks to fit (smaller chips, then no group labels, then a slight zoom) so the steps and buttons can no longer run into each other.'] },
  { v: '0.90.3', title: 'Centre bar tidy', notes: ['Every step chip and the Next phase / Next turn / Declare attackers buttons in the middle bar now share one height, font size and pill shape, and sit together in a single row with the buttons grouped on the right.'] },
  { v: '0.90.2', title: 'Sideboarding and a roomier table', notes: [
    'Sideboarding now lives on the deck screen: open Your decks, press Sideboard on a deck box, and swap cards one copy at a time between main deck and sideboard. Your saved decklist is never changed, and Restore original brings it back exactly.',
    'A deck that is currently sideboarded has a gold Sideboard button, and new games use the sideboarded list. Editing the decklist itself clears the swaps.',
    'The turn tracker in the middle of the battlefield now holds Next phase and Next turn. The old phase row above the battlefield is gone, which frees space, so the battlefield is taller.',
    'Less repetition: floating mana is shown once (top bar), the land-drop note moved to the Lands label, the in-game Sideboard button is gone, Tokens moved to the top bar, and the status icons are smaller.'] },
  { v: '0.90.1', title: 'Cast flight and discarding in your hand', notes: [
    "When you cast a spell, the card now flies from your hand to the middle of the board and stays there while it is on the stack. When it resolves it flies to where it belongs: creatures and other permanents to the battlefield, instants and sorceries to the graveyard. A countered spell flies to the graveyard tinted red. This replaces the old spotlight for your own spells; the new 'Cast & resolve flight' switch in Settings > Animations turns it off (the spotlight comes back).",
    "Choosing cards to discard now happens in your hand. Every card you may discard glows, the others dim, and a bar over the hand says 'select 2 cards to discard (0/2)' with a Discard button. A chosen card shows a red DISCARD tag. This is used for cleanup, for 'draw, then discard' effects such as Faithless Looting and Territorial Kavu, and for discard costs. The centre pop-up is gone.",
    "Version numbers will now move in smaller steps, and the README has a 'Road to 1.0' plan focused on following the Comprehensive Rules more closely."
  ] },
  { v: '0.90.0', title: 'Cards that were done by hand', notes: [
    "Necrodominance: while it is on the battlefield, a 'Skip draws' icon appears in the top bar. Switch it on and every card you would draw is skipped (your draw step too); switch it off to draw normally. It shows even if you turned the state icons off.",
    "Goryo's Vengeance: the creature now gains haste as well as returning and being exiled at the next end step (the newer card text says 'gains haste' without 'until end of turn', which the app did not recognise).",
    "Time Vault: when you press Next turn while it is tapped, a window asks if you want to skip that turn. Skipping untaps it (an extra turn can be skipped the same way). Tutor mode has a switch for this prompt.",
    "Hullbreacher: when you tell the app your opponent drew an extra card (the card button next to their life), the draw is replaced by a Treasure token for you, and Bowmasters-style 'whenever an opponent draws' abilities do not trigger.",
    "Wan Shi Tong: a new magnifier button next to your opponent's life says 'my opponent searched their library'. Wan Shi Tong then gets a counter and you draw. Any other 'whenever an opponent searches' card works the same way.",
    "Vren's 'exile instead of dying' line is now shown as information: it only matters for your opponent's creatures, which the app does not track. Do it by hand if you play out an opposing board."
  ] },
  { v: '0.89.0', title: 'Settings redesign; borders and colour sets removed', notes: [
    "Removed the colour sets (guilds, shards, wedges) and the battlefield border decorations. If you had one selected, your playmat and sleeve go back to the Kitchen table and Worn old card back; your frame colours stay as you left them.",
    "The Settings window is rebuilt: a sidebar of tabs on the left (Look & feel, Board, Animations, Sound, Tutor mode), a title and one-line description for each tab, and a search box that looks through every tab at once.",
    "The old 'Layout' tab is now part of 'Board', next to the playmat and frame, so everything about the table is in one place. 'Graphics' became 'Look & feel'.",
    "Checkboxes are now on/off switches, section headings are clearer, and the window is wider so descriptions do not wrap so much. On a narrow screen the sidebar becomes a row of tabs."
  ] },
  { v: '0.88.2', title: 'Border corners', notes: [
    "The four border strips used to overlap where they met, so the corners looked doubled up. Each strip is now cut on a diagonal (a mitred join, like a picture frame) so the corners meet cleanly."
  ] },
  { v: '0.88.1', title: 'Slimmer, finer borders', notes: [
    "The battlefield borders now take about 40% less room (the default band is 26 px instead of 44; the Border size slider still goes from half to double).",
    "Every border has more fine detail: flame tongues and sparks, a second thin vine with tiny leaves, flowers and thorns, wisps of smoke, a vertebrae row and ribs on the bones, snowflakes and frost lace, wave arcs and foam curls, and extra filigree on the gilded scrollwork. The art is drawn at full size and scaled down, so the detail stays crisp."
  ] },
  { v: '0.88.0', title: 'Linked steps: draw then discard', notes: [
    "Cards like Faithless Looting, Merfolk Looter, Careful Study and Prismari Command (its draw-two-discard-two mode) were only read as 'draw'. Now the app understands the whole sentence as one effect in order: 'draw two cards, then discard two cards'. After the draw, a window makes you choose exactly that many cards to discard. There is no 'choose nothing' button, because the discard is part of the effect, not an option.",
    "Works in either order ('discard two, then draw two'). If your hand has fewer cards than you must discard, you discard them all and the effect carries on (rule 701.8). 'If you do' wording skips the rest when the earlier step did nothing.",
    "Resolve now applies these automatically, and the leftover keyword line (Flashback, Kicker, Cycling and so on) no longer stops the auto-apply, because the cast window already handles it.",
    "Territorial Kavu: the card text in my data only says 'exile target card from a graveyard' when it attacks, with no discard. If your copy says something different, send me the exact text."
  ] },
  { v: '0.87.0', title: 'Colour sets, sleeves and battlefield borders', notes: [
    "New 'Colour sets' section in Settings > Playmat & frame: 26 sets (5 colours, 10 guilds, 5 shards, 5 wedges, 5-colour). One click gives you a matching playmat, card sleeve, 3-colour board frame and border decoration. You can still change any piece afterwards.",
    "Border decorations drawn along the edges of the battlefield: fire, vines, smoke, bones, frost, tides and runes. They sit behind your cards. Each has its own on/off, a size slider and an animate toggle (animation respects reduced-motion).",
    "The playmat and sleeve galleries also list every set, and the interface accent can follow the set you pick.",
    "All art is drawn by code, so it will not match real playmats. Tell me what looks off and I will tune it."
  ] },
  { v: '0.86.0', title: 'Card definitions from your decks', notes: [
    "I went through your deck scan report and fixed the cards the app got wrong or skipped. Every fix below was checked against your own card text.",
    "Bug fixed: current Magic card text says 'this creature' where older text used the card's name, and the app only understood the name. So Dragon's Rage Channeler's delirium (+2/+2 and flying) never switched on. It does now, and the same fix helps every card worded that way.",
    "Twinned Vision draws two cards when you flash it back (it was drawing one). Requiting Hex only offers its 2 life if you paid the optional extra cost, and Foul-Tongue Invocation only offers its 4 life as an option you confirm (it used to offer it every time).",
    "New costs the app can pay: 'blight 1' (puts a -1/-1 counter on a creature you control) and 'reveal a Dragon card from your hand'.",
    "Tribal Flames counts your basic land types. Orcish Bowmasters now amasses (creates or grows your Orc Army). Wan Shi Tong draws half X and puts X counters on itself. Mossborn Hydra doubles its counters. Kappa Cannoneer triggers when another artifact enters. Search for Azcanta surveils, then offers to transform at seven cards in your graveyard. Mana Vault asks you to pay {4} to untap.",
    "Black Lotus (and every other mana ability that taps or sacrifices) now adds its mana at once instead of waiting on the stack, which is the real rule: mana abilities cannot be responded to.",
    "Trinisphere now raises the cost of cheap spells to three. Icetill Explorer and Mole Man let you play lands from your graveyard (open the graveyard and press Play land).",
    "Activated abilities: double-click a creature that has a usable ability (Psychic Frog) and a chooser lists each ability with an Activate button, plus 'Tap it instead'. Abilities with no timing restriction can be used any time you have priority, including with something already on the stack; the green outline shows when one is ready.",
    "The stack in the middle of the table now has Pass priority, Countered and Resolve top buttons right under it, so you can resolve without going to the side panel.",
    "When you press Resolve and exactly one clear effect applies (a +1/+1 counter, drawing a card, damage to a target you chose) it is applied at once with no pop-up. The pop-up only appears when there is a real choice (more than one effect, 'you may', looking at cards, searching). Turn this off in Settings > Teaching: 'Auto-apply obvious effects'.",
    "Board frames can now use three colours (edge, highlight and accent). Every preset has a third colour, and Custom has a third picker.",
    "Still by hand: Necrodominance's 'skip a draw', Wan Shi Tong's opponent-search trigger, ward and the other rules about your opponent's cards (a goldfish game has no opponent board)."
  ] },
  { v: '0.85.0', title: 'Linux and Steam Deck support', notes: [
    "MTG Playtester can now be built for Linux and the Steam Deck as a single AppImage file (Build-Linux.sh, or the new 'Build Linux app' action on GitHub). Run it in Desktop Mode, or add it to Steam as a non-Steam game.",
    "Also new for Linux: Run-Linux.sh (runs it from the folder) and Start-Browser.sh (opens it in your browser with nothing to install).",
    "The table was checked at 1280×800, the Steam Deck's screen size, and the turn tracker is tighter on small screens so its text no longer overlaps.",
    "The game itself is unchanged. This update only matters if you want to run it on Linux."
  ] },
  { v: '0.84.0', title: 'Murktide Regent ruling fixes', notes: [
    "Murktide Regent now enters with one +1/+1 counter for each instant or sorcery card exiled with it, meaning the cards you delved away while casting it. Before, it always got a single counter no matter what you delved. Lands and other card types you delve do not count, and casting it without delve gives no counters.",
    "New 'leaves your graveyard' trigger support (rule 603.10a): whenever an instant or sorcery card leaves your graveyard while Murktide Regent is on the battlefield, it gets a +1/+1 counter. This fires when a card is exiled by delve for another spell, cast with flashback or escape, returned to hand, shuffled in, or moved by hand from the graveyard viewer. Cards entering the graveyard do not trigger it, and delving for Murktide itself does not either, because it is still on the stack.",
    "Other 'enters with counters for each…' cards that the app cannot count now tell you to add the counters by hand, instead of silently giving one. The card scanner shows those lines as partly understood."
  ] },
  { v: '0.83.0', title: 'Look-and-sort effects, adjustable numbers, longer tour', notes: [
    "New general 'look at the top N cards and sort them' tool. When a card says 'Look at the top three cards of your library. Put one into your hand, put one on the bottom, and exile one. You may play the exiled card this turn', the app now shows the top cards and lets you choose where each one goes, checks the counts, and marks the exiled card playable this turn. This fixes Expressive Iteration and works for any card worded the same way (for example 'put one into your hand and the rest on the bottom').",
    "Exile viewer: cards you may play this turn show a Cast or Play land button; lands use your land drop. They stop being playable when the turn ends.",
    "Library menu: the number box now applies to Look at top N too (it used to always look at 10), remembers your last number, and Look at top N has new buttons: Exile (play), Graveyard and Bottom. Scry and Surveil windows have a 'Cards to scry' box so you can change the number when an effect needs more or fewer.",
    "The Welcome tour can now also be opened from Settings, and it has new pages on what the icons and colours mean, what 'understood / partly / by hand' mean, and how updates work."
  ] },
  { v: '0.82.0', title: 'Attackers look tapped, and a rules audit', notes: [
    "Attacking creatures were already being tapped (unless they have vigilance), but the combat lane's styling hid the sideways turn, so they looked untapped. Tapped attackers now show turned sideways again.",
    "I ran a baseline rules audit of 33 checks: untap step, summoning sickness and haste, defender, attacking and vigilance, one land per turn and land timing, sorcery vs instant timing, mana emptying between steps, draw per turn, discard to seven, damage wearing off, lethal damage, legend rule, tokens ceasing to exist, stack order, and tapped lands.",
    "The audit found three real gaps, now fixed: +1/+1 and -1/-1 counters on the same permanent now cancel out; a planeswalker at 0 loyalty now goes to the graveyard; and ten poison counters, or drawing from an empty library, now show that you would lose the game."
  ] },
  { v: '0.81.0', title: 'Welcome tour, and turn 1 starts in Main 1', notes: [
    "New Welcome tour: a short walkthrough that opens the first time you launch the app. It covers card data, importing a deck, starting a game, playing cards, the Settings tabs, custom playmats and sleeves, Tutor mode, and how the app reads cards. Reopen it any time from the gear menu (Welcome tour…). It does not appear for people who already have decks or card data.",
    "The first turn of a game now skips the beginning phase and starts in Main phase 1. On the draw you still get your draw."
  ] },
  { v: '0.80.0', title: 'Hand-written card definitions', notes: [
    "New layer: a card can now have a hand-written definition that says exactly what each of its lines does. It is checked before the general text reader, so a defined card never depends on guesswork, and the card scanner shows its lines as understood with a 'Hand-written definition' note.",
    "First definition: Sink into Stupor. A spell it returns now leaves the stack and goes on top of its owner's library instead of to hand; a permanent returns to hand.",
    "Cards without a definition behave as before. More definitions need your decklists, so the next step is covering your actual decks."
  ] },
  { v: '0.79.0', title: 'Casting from the graveyard', notes: [
    "Flashback, escape and aftermath now work. Open your graveyard and a card you can cast from there gets a Flashback / Escape / Cast button. It goes through the normal cast flow with the right cost (flashback cost, or escape mana plus exiling the stated number of other graveyard cards), and the usual timing rules apply.",
    "A card cast with flashback or aftermath is exiled instead of going anywhere else once it leaves the stack. Backing out of the cast puts it back in the graveyard.",
    "Snapcaster Mage style effects ('gains flashback until end of turn') now let you pick the instant or sorcery; open the graveyard that turn to cast it for its mana cost.",
    "Not done: retrace, jump-start, disturb, unearth, and casting from exile other than adventures."
  ] },
  { v: '0.78.1', title: 'Stacked cards fan out', notes: [
    "Identical lands, tokens and enchantments that pile into one card now show a slight fan behind it at rest, so you can tell it is a stack.",
    "Hover the pile and the fan spreads wider, one sliver per extra card (up to four shown), so you can see roughly how many there are. The count badge still shows the exact number and clicking it still spreads them out."
  ] },
  { v: '0.78.0', title: 'Stack lock, hover fan for graveyard and exile', notes: [
    "While anything is on the stack, Space, N, D, U, S, Next phase, Draw, Untap all and the turn tracker steps are locked and a toast tells you why. Respond with an instant or ability, or resolve / counter the top item first. The spell still shows in the middle of the table.",
    "Graveyard and exile piles now fan out their top three cards only while you hover them; click a pile to open the whole zone. The name list that used to pop up on hover is gone, since the zone counts and state icons already cover it.",
    "The 'Fanned graveyard' switch is now 'Fan graveyard / exile on hover'."
  ] },
  { v: '0.77.0', title: 'Adventure / split cards, and honest "understood"', notes: [
    "Adventure, split and aftermath cards now have real halves. Casting one asks which half; the half's own cost, targets and effect are used. An adventure goes to exile 'on an adventure' and you can then cast the creature from exile (Exile viewer has a Cast creature button). Backing out of the prompt puts the card back where it was.",
    "The card scanner is stricter: a line counts as understood only if the app carries out every sentence of it. Extra clauses the app does not apply (for example Sink into Stupor's 'put it on top of the library' sentence) now show as 'by hand' with the missed sentence quoted, so deck reports will look worse but are truthful.",
    "Not done yet: casting the back half of an aftermath card from the graveyard, and other graveyard casting (flashback, escape)."
  ] },
  { v: '0.76.1', title: 'Turn tracker floats across the battlefield', notes: [
    "The turn tracker is back to floating between the creature lane and the lands, now stretched across the whole battlefield and showing every step of the turn with the current one lit. It no longer has its own row, so the battlefield grows taller.",
    "It sits in a reserved gap between the lanes so it never covers a card, and it stays visible while the stack is up (the floating stack card passes in front of it)."
  ] },
  { v: '0.76.0', title: 'Turn tracker replaces the Now / Next box', notes: [
    "The strip under the top bar now shows the whole turn: Beginning (Untap, Upkeep, Draw), Main 1, Combat (Begin, Attack, Block, Damage, End), Main 2 and Ending (End step, Cleanup). The step you are in is lit gold, finished steps are dimmed and the group you are in is outlined. Hover a step for what happens there; click a later step to skip ahead to it.",
    "It replaces the old Now / Next box, no longer floats over the board, and stays visible while the stack is up. It still shows your floating mana, land drop and the stack count.",
    "Turn it off under Settings > Playmat & frame > Turn tracker strip to bring the old Now / Next box back. The Layout tab's 'Phase tracker above your hand' option is gone since the tracker has its own place now."
  ] },
  { v: '0.75.0', title: 'Game-state icons; card preview back in the right column', notes: [
    "New row of pictures in the top bar that light up while a game state applies: Storm (with the number of spells cast this turn, yours and your opponent's), Monarch, Initiative, the city's blessing (Ascend), Day / Night, Delirium, Threshold, Metalcraft, Revolt, Morbid, Landfall, and Energy, Poison and Experience counters. Hover one for the rule.",
    "The app lights Storm, Delirium, Threshold, Metalcraft, Revolt, Morbid, Landfall and the city's blessing (at ten permanents) by itself. Click Monarch, Initiative or Day/Night to set them; click a counter to add one and right-click to remove one. Being the monarch queues the end-step draw, and the initiative queues the upkeep venture.",
    "Switch them off under Settings > Tutor mode > Game-state icons.",
    "The enlarged card preview is back in the right column and no longer follows your pointer. The Layout tab's 'Floating card preview' became 'Slimmer right column' (286px) so the board stays wide."
  ] },
  { v: '0.74.0', title: 'New layout option (Settings > Layout)', notes: [
    "New Settings > Layout tab: choose Updated or Original. The table switches the moment you pick, so you can compare and go back any time.",
    "Updated layout, each part with its own switch: two lanes (creatures centred in one wide lane; lands and other permanents share a band below), a slim zone rail for library / graveyard / exile, a floating card preview that follows your pointer (the right column shrinks to the stack and log), the phase tracker moved just above your hand, and one pile per land name.",
    "Lands now pile by name even when some are tapped: the pile shows how many are tapped, clicking it taps an untapped copy (or untaps one when all are tapped). Click the ×N badge to spread them out.",
    "Stacking identical lands and tokens already existed (v0.67, Playmat & frame); this builds on it."
  ] },
  { v: '0.73.0', title: 'Real card faces (flip cards, double-faced lands)', notes: [
    "Transform and modal double-faced cards are now read one face at a time. Before, both faces' rules were glued into one card, so Delver of Secrets (a 1/1) was treated as having flying, and Sink into Stupor's land text leaked onto the spell.",
    "Right-click a transform card on the battlefield and choose Transform. A trigger that says 'transform' offers it too. Delver's upkeep trigger now looks at your top card, shows it, and transforms only if it is an instant or sorcery. A transformed card is its back face for everything (name, type, power/toughness, abilities) and is its front face again once it leaves the battlefield.",
    "A spell with a land on its back (Sink into Stupor // Soporific Springs): right-click it in your hand and choose 'Play Soporific Springs (land)'. It uses your land drop and enters as that land.",
    "The card reader now judges each face on its own and labels back-face lines. Fixed 'NaN' at the end of the notes for modal cards (Kolaghan's Command, Pick Your Poison).",
    "Split, aftermath and adventure cards still use the old combined reading; they are next. Cards saved before this version are converted when the app starts; the back face's power/toughness appears after you reload card data."
  ] },
  { v: '0.72.0', title: 'Tapping for mana follows the rules', notes: ["A land or mana rock you tapped for mana remembers it. If you untap it while that mana is still floating, the mana is taken back out of your pool (and any life or damage the tap cost is given back), like undoing the tap.", "Once the mana has been spent, or has emptied from your pool, the permanent stays tapped: clicking it explains why. A card that untaps it does work: right-click it and choose “Untap (a card effect untaps it)”. Untap effects the app resolves itself (“untap target…”, “untap this”) use that path automatically, and your untap step untaps everything as usual.", "Lands you tapped to pay a spell or ability cost always stay tapped. “Tap without floating mana” (right-click) is still a plain tap you can undo freely, for things the app does not track."] },
  { v: '0.71.3', title: 'Abilities on the stack show their card', notes: ["Triggered and activated abilities on the floating stack now show the picture of the card they come from, with the ability's text in a caption on it, instead of a plain text card. (Before, only spells used pictures.)"] },
  { v: '0.71.2', title: 'Status bar no longer covers the stack', notes: ["The small phase / mana / land-drop bar in the middle of the table is hidden while something is on the stack, so it can no longer sit on top of the floating stack card. It comes back when the stack is empty."] },
  { v: '0.71.1', title: 'More room on the battlefield', notes: ["The library, graveyard and exile column is narrower and sits further right, so the three battlefield zones are wider. The artifacts/enchantments zone is now about as wide as the lands zone and the bottom row is taller.", "Artifacts, enchantments, planeswalkers and lands wrap onto a second row and shrink a little when crowded instead of scrolling sideways, so there is no more scroll bar in the artifacts zone.", "Fixed the shrink-to-fit sizing when card pictures are on: it used the size of the text tiles, so tall picture cards could still overflow."] },
  { v: '0.71.0', title: 'Backup card data source and clear network errors', notes: ["Card data now has a second public source. If Scryfall cannot be reached, the app switches to the MTGJSON project's AtomicCards file by itself. “Use MTGJSON only” in Card data skips Scryfall. You can also load an AtomicCards (or ModernAtomic, LegacyAtomic…) file you downloaded yourself with “Choose file…”.", "Downloads now retry politely (rate limits and short outages) and say why they failed in plain words: offline, too many requests, refused by a VPN or firewall, or the site is down. The “Images: offline” chip shows the reason when you hover it, and clicking it tries again. One hiccup no longer stops the whole picture download.", "Pictures still come from Scryfall only. If you cannot reach it, Custom card art (deck screen) lets you use your own images.", "For the MTGJSON download to work from the installed app, the app shell needs this version's main.js (install the full package once). Without it, download the file in your web browser and use Choose file…"] },
  { v: '0.70.2', title: 'Clean importer, .txt decklists, floating stack', notes: ["“Import / new deck…” now opens a completely blank importer. It no longer shows the last deck you imported. (Editing a deck with its Edit button still shows that deck.)", "Decklist files: the importer has a “Load .txt file…” button. Pick one file and it fills the name and list for you to check and save; pick several and each becomes its own deck. You can also drag a .txt file onto the app window.", "Fixed the stray word “null” in Settings > Graphics (it was in the card sleeve section).", "The stack now floats in the middle of the table: your spells and abilities, and your opponent's, shown as cards (top of the stack largest). While you drag a card from your hand onto it, it lights up green and the card is cast in response; drag a permanent onto it to activate its ability."] },
  { v: '0.70.1', title: 'No more scroll bars', notes: ["The right-hand column no longer scrolls. The card preview now shrinks to fit whatever room the stack and game log leave, so the whole column always fits on screen.", "Every other scrolling area (zones, windows, the full game log) now uses a hair-thin bar that stays invisible until you hover over it."] },
  { v: '0.70.0', title: 'Permanent stack panel, tidier top bar and log', notes: ["The stack now has a permanent, prominent spot on the right. When something is on the stack the panel lights up with a count badge, bigger rows and Pass priority / Countered / Resolve top buttons. It never covers the table, so everything you can cast or activate in response stays clickable (still outlined in green). The old “Stack / opponent spell” box is gone; the Stack button in the top bar jumps to the panel. On very narrow windows without the right column it still opens as a small floating tray.", "The Game log shows just the last two lines. “Show all” opens the full log; the choice is remembered.", "The top bar status chips are short (“Images: offline”, “Card data: 197 cards”) and shrink before they ever push the version button out of the window."] },
  { v: '0.69.3', title: 'One-row combat, old kitchen table', notes: ["Declaring attackers no longer makes a second row you have to scroll to. Attackers stay at the front of the one creature row, step forward over the zone edge with a gold outline, and every creature that is not attacking tucks to the side, overlapped (hover one to bring it forward). Turn it off with Settings > Board layout > Combat lane.", "New playmat “Old kitchen table”: plank wood grain, knots, scratches and a coffee-cup ring stain. New card back “Worn old card back”: a plain brown card back that is creased, bent at the corner and scuffed.", "Both are switched on once automatically if you had not picked a mat or sleeve before; change them any time in Settings > Graphics."] },
  { v: '0.69.2', title: 'Cleaner stack, priority in paused steps', notes: ["The stack is now a floating tray instead of a window that covers the table. Each spell or ability is a card-like row (TOP marked), and the old list of castable cards is gone: cards you can cast or activate in response now glow with a pulsing green outline, and other hand cards fade back.", "Fixed: Thespian's Stage (and other lands with abilities) could not be activated in your upkeep or draw step. The “Pause at phase” aid was wrongly treating the pause as having no priority. You now have priority in every paused step except untap and cleanup; only a triggered ability waiting to go on the stack holds things up (press Continue and it resolves first).", "Lands with activated abilities (Thespian's Stage, manlands) now get the green “can activate” outline too."] },
  { v: '0.69.1', title: "Mishra's Bauble drew twice", notes: ["Fixed: Mishra's Bauble (and any “draw a card at the beginning of the next upkeep” effect) offered the delayed draw twice, once automatically and once as a “Create delayed trigger” button. Pressing the button made you draw two cards. The duplicate button is gone and the delayed draw can only be set once per ability."] },
  { v: '0.69.0', title: 'Custom card art', notes: ["On the deck screen (Your decks) every deck now has an “Import custom card art…” button. It opens a grid of that deck's cards where you can choose your own picture for any card, change it, or reset it.", "“Import several images…” matches many files at once by file name (for example “Lightning Bolt.png”) and tells you which ones did not match.", "Custom art shows on the table, in your hand, in the card preview and on the deck box. It is saved on this computer, only applies to that deck, and is removed when you delete the deck. Pictures are shrunk to card size so they stay fast."] },
  { v: '0.68.0', title: 'Physical card drag', notes: ["Click and hold a card and the card itself follows your mouse, tilting as you move it, and rises above everything else.", "Release it on a zone that takes it and it happens: a land is played, a spell is cast, a battlefield card goes to the graveyard, exile, library or hand, and a hand card dropped in your hand reorders it.", "Release it anywhere else, or on a zone where the move is not allowed right now (wrong phase, land drop already used), and the card flies back to where it came from. Escape cancels a drag the same way.", "Switch: Settings > Animations > Physical card drag. Turned off, you get the old browser drag (and dropping anywhere on the table plays the card on the battlefield)."] },
  { v: '0.67.2', title: 'Hand on top, drop anywhere, safer web update', notes: ["Hand cards now always rise above everything else on the table when you hover them. Before, the enlarged card was clipped under the battlefield.", "You can drop a card anywhere on the table: a drop that misses a specific zone or pile lands on the battlefield (a hand card is played, any other card is moved there). Dragging a battlefield card back onto the board does nothing.", "Update app: the web address button used to download and install immediately while being called Check online, which made the app seem updated. It is now called Download & install from this address, asks first, and the GitHub Check now button only ever looks."] },
  { v: '0.67.1', title: "Thespian's Stage and {T} ability payment", notes: ["Thespian's Stage now works: its ability lets you pick a land and it becomes a copy of it, keeping its own copy ability, its counters and whether it is tapped. Copying Dark Depths makes the 'no ice counters' trigger fire (Marit Lage). It becomes Thespian's Stage again if it leaves the battlefield.", "Fixed: an ability with {T} in its cost could also tap its own permanent to pay for its mana cost. A permanent that is tapped as part of an ability cost can no longer be used as a mana source for that same ability."] },
  { v: '0.67.0', title: 'Board layout pass', notes: ["Six board changes, each with its own switch in Settings > Playmat & frame > Board layout.", "Zone depth: the three battlefield zones look like shelves with a soft inner shadow.", "Stack identical lands and tokens: identical cards pile into one with a count badge; click the badge to spread them out, and click it again to pile them up. Cards with counters, attachments or different states stay separate.", "Dim cards that cannot act: tapped lands and summoning-sick creatures are a little duller.", "Mana and phase strip: a slim strip on the board edge shows the current step, what comes next, floating mana, your land drop and the stack size.", "Combat lane: once attackers are declared, they move to a lit lane at the front of the creature zone.", "Fanned graveyard: the top three graveyard cards show fanned out."] },
  { v: '0.66.1', title: '3D hand and floating battlefield', notes: ["Your hand cards now tilt toward the mouse in 3D when you hover them, the same tilt as the big card preview. Switch: Settings > Animations > 3D hand tilt.", "Battlefield cards float: each drifts up and down a tiny amount at its own pace and has a deeper shadow, so the board feels layered. Switch: Settings > Animations > Floating battlefield. Both follow the master animation switch and the system reduced-motion setting."] },
  { v: '0.66.0', title: 'Online updates from GitHub', notes: ["Update app now has a From GitHub section: Check now shows the newest release and what changed, then Download & install fetches the files and checks each one against its published SHA-256 fingerprint before installing. Nothing is installed if a check fails.", "Optional switch: check for updates when the app starts (on by default, quiet if you are offline). A dot appears on the Update app button when a release is waiting.", "This version changes the desktop shell, so install the full package once (Build-Installer.bat or Run-Desktop.bat from the new folder). After that, updates arrive from GitHub."] },
  { v: '0.65.0', title: 'More triggers: graveyard, discard, Sagas', notes: ["Triggers that work from the graveyard now fire from there: Ichorid at your upkeep, Bridge from Below, and 'when this is put into your graveyard' cards such as Narcomoeba (from the library) and Emrakul, the Aeons Torn.", "New events: a card put into your graveyard from anywhere (Murktide Regent counts instants and sorceries), cycle and discard triggers (Curator of Mysteries), 'whenever you tap this for mana' (Forbidden Orchard) and 'whenever you lose life'.", "Sagas work: they enter with a lore counter, gain another each precombat main phase, each chapter triggers when the count reaches it, and the Saga is sacrificed once the final chapter has resolved. 'Gains \"...\"' chapters (Urza's Saga) really give the land its mana ability and the Construct ability.", "New effects: shuffle graveyard into library, put this onto the battlefield from the graveyard, Ichorid's exile-and-return, exile this from the graveyard, and tutors for 'mana cost {0} or {1}'. Colour words now work in search and graveyard filters.", "Official rules used: 603.6 (zone-change triggers), 603.10a (leaves-the-battlefield look back), 714 (Sagas)."] },
  { v: '0.64.0', title: 'Attachments and replacement effects', notes: ["Equipment and Auras now really attach. Equip is a sorcery-speed ability you activate (pay the cost, pick a creature you control). Auras ask what to enchant as they enter (and go to the graveyard if there is nothing, rule 704.5m). Right-click an Equipment or Aura for Attach to… / Unattach. A badge on each tile shows what it is attached to.", "Attachment bonuses follow the host live: Bonesplitter +2/+0, Batterskull +4/+4 with vigilance and lifelink, Rancor +2/+0 and trample, Lightning Greaves haste and shroud, Cranial Plating +1/+0 for each artifact you control, Pacifism removes it from your attackers. Living weapon creates the 0/0 Germ and attaches the Equipment to it. When a host leaves, Auras fall to the graveyard and Equipment stays unattached.", "Replacement effects: Hardened Scales and Winding Constrictor add counters (also as a permanent enters, e.g. Walking Ballista with X counters), Doubling Season doubles counters from effects; manual +/- counter buttons are never changed. Mox Diamond asks you to discard a land or goes to the graveyard. Cavern of Souls, Phyrexian Revoker and Pithing Needle ask for a creature type or card name as they enter; Revoker and Needle block activating the chosen card's abilities, and Cavern's coloured mana is limited to creature spells of the chosen type.", "Dredge: when you would draw (draw step, 'draw a card' effects) and have a dredge card in your graveyard with enough cards in your library, you are asked whether to mill and return it instead. New switches in Settings > Tutor mode: Dredge prompt and Replacement effect notes.", "Test set scan: 0 lines not understood; lines understood rose from 66% to 74%."] },
  { v: '0.63.1', title: 'Scan decks & save report', notes: ['New button on the Your decks screen: Scan decks & save report. It reads every card of every saved deck, lists each line the app does not fully handle with the reason, and saves mtg-playtester-deck-report.txt that you can upload for review. Cards missing from the card data are listed too.'] },
  { v: '0.63.0', title: 'No unknown lines: rulings, tutors, land drops', notes: ["The card reader now has no 'not understood' lines on a 190-card test set of Modern, Legacy and Vintage staples (it started at 49). Every line that the app cannot automate now carries the official rule to follow by hand, instead of a vague flag. Cards the app handles partly are still shown in gold.", "Extra land drops: Exploration, Azusa, Dryad of the Ilysian Grove, Oracle of Mul Daya and similar now allow more than one land per turn (cumulative, rule 305.2). Before this, only one land per turn was ever allowed.", "Black Lotus and Lion's Eye Diamond now give three mana of one colour (they gave one). Manamorphose-style 'N mana in any combination of colors' asks for each mana. Take an extra turn (Time Walk, Emrakul) is offered and logged.", "Tutors and graveyard returns: 'Search your library for…' (Demonic Tutor, Entomb, Stoneforge, Recruiter, Tinker, Primeval Titan…) opens a picker with matching cards highlighted and a Find nothing button (you may always fail to find). 'Return up to three land cards from your graveyard to your hand' (Life from the Loam) opens a graveyard picker.", "'Can't be countered' is enforced (Emrakul). 'Doesn't untap during your untap step' (Mana Vault) and Back to Basics now keep permanents tapped. Enters with X counters (Chalice of the Void) uses the X you paid. Coin flips (Mana Crypt) flip and deal the damage. 'Gets +1/+1 as long as you control a Mountain' (Wild Nacatl) is live.", "Legendary cards that call themselves by their short name (Phlage, Ajani, Karn) are now read correctly, and 'enters or attacks' triggers fire on both. Adventure and split cards read their second face as an instant or sorcery.", "New format filter in 'Scan every card': Standard, Pioneer, Modern, Legacy, Vintage, Pauper or Commander. Re-import the Oracle file once to enable it. Use it on your real data and send me the report to find the next gaps."] },
  { v: '0.62.0', title: 'Lands: Temple, tomb, Vesuva, Dark Depths, Locus', notes: ['Lands are now read from their rules text. {T}: Add {C}{C} lands (Eldrazi Temple, Ancient Tomb, Urza\'s tron lands with their bonus) make all their mana, with each mana shown in the pay window; Ancient Tomb and similar lands deal their damage; Mana Confluence / City of Brass cost their life or damage.','"Spend this mana only to cast colorless Eldrazi spells…" is enforced when you pay through the cast window: Eldrazi Temple gives {C}{C} for a colorless Eldrazi spell and only {C} for anything else. (Mana you float by tapping a restricted land by hand is not tracked; the app reminds you.)','Vesuva asks which land to copy when it enters; it enters tapped with that land\'s name, abilities and enters-with counters, and turns back into Vesuva when it leaves.','Dark Depths: enters with ten ice counters (any "enters with N <kind> counters" now works), counters of any kind show on the card, "{3}: Remove an ice counter" is offered, and when the last one is gone the "When it has no ice counters" trigger fires: Exile Dark Depths, then create Marit Lage (20/20 legendary, flying, indestructible) in one step. Tokens now really have flying/indestructible etc.','Locus lands: Cloudpost adds {C} for each Locus on the battlefield, Glimmerpost gains 1 life for each Locus, and Vesuva copying a Locus counts as one. "For each <type or subtype>" counting works for these effects in general.'] },
  { v: '0.61.0', title: 'Token tray and Kozilek\'s Command', notes: ['New Tokens button (next to Sideboard): the app reads the rules text of every card in your deck and lists each token it can make (Eldrazi Spawn, Treasure, Clue, Orc Army, Spirit with flying…) with its power/toughness, abilities and the cards that make it. Pick a number and press Create to put them onto the battlefield.','Tokens now carry their real abilities and keywords: an Eldrazi Spawn can be sacrificed for {C}, a Treasure for any colour, a Clue for a card, a token with flying counts as flying, and tokens have proper types and subtypes.','Fixed the effect reader for "creates": Kozilek\'s Command (and every "target player creates X tokens" card) now offers Create X tokens, using the X you paid, and no longer mistakes the token\'s own "Add {C}" for a mana ability. If the target is your opponent the tokens are only logged. Target parsing for "target player creates…" is fixed, and the stack shows the real X in chosen modes.'] },
  { v: '0.60.0', title: 'Smoother, centred hand and tabbed settings', notes: ['The hand is always centred: the middle card sits in the middle of the hand zone however many cards you hold, and drawing or playing slides the others smoothly to their new places (cards now glide and re-angle instead of snapping).','New Animations fine-tuning: animation speed, hand fan curve, sparkle amount and spell spotlight size.','Settings are split into tabs: Graphics (card size, sleeves, interface theme, foil, cursor), Playmat & frame, Animations, Sound and Tutor mode.'] },
  { v: '0.59.0', title: 'Amass and Orcish Bowmasters', notes: ['Amass now works (rule 701.47): put N +1/+1 counters on an Army you control; if you control none, a 0/0 black Army token is created first. The Army also becomes the named type (Orc) in addition. With several Armies you choose which one.','Orcish Bowmasters triggers on entering and its Amass Orcs 1 follows the damage. For the "whenever an opponent draws a card except the first one in their draw step" half, use the new 🃏 button beside the opponent life: say whether it was their draw-step draw or an extra draw.'] },
  { v: '0.58.0', title: 'Animations, effects and themes', notes: ['Cards now move: drawn cards fly from the library into your hand (staggered when you draw several), played cards slide from hand to the battlefield, tapping rotates smoothly, and cards leaving fly to the graveyard, exile or stack. Permanents pop in with sparks.','Spell spotlight: casting a spell lifts the card into the middle of the screen with a glow in its colour, then sends it to the stack; resolving and countering have their own effects.','Life totals roll up or down, flash green or red, shake on big hits, show floating +/- numbers, and a lethal moment appears at 0.','A turn banner at the start of each turn and a flash on the phase bar when the phase changes.','Your hand sits in a gentle fan and the hovered card lifts.','Text card tiles have a new look: colour-tinted frames, a name plate, a type bar and a stat plate.','Settings \u2192 Animations & theme: a switch for each effect and eight interface themes (Midnight, Obsidian & gold, Abyss blue, Forest, Neon, Parchment, Light, Match my deck).'] },
  { v: '0.57.0', title: 'Deck boxes', notes: ['The deck drop-down is now a Deck button that opens a shelf of 3D deck boxes. Each box shows art from one card of that deck (the first non-land card by default; "Art…" lets you choose), the deck name on the spine, its card count and colours. The boxes tilt toward your mouse. Click a box to use that deck; "Edit" opens that deck in the editor.'] },
  { v: '0.56.0', title: 'Built-in sleeves and playmats', notes: ['Settings now has a gallery of 9 card sleeves (Mana wheel, Dragon scale, Arcane circle, Forest, Tides, Ember, Gilded deco, Night sky, Checker) and 10 playmats (Mana sigil, Dragon\'s lair, Arcane circle, Ocean depths, Mountain dusk, Moonlit grove, Old map, Obsidian & gold, Nebula, Storm). Click one to use it. They are drawn by the app, so there is nothing to download. Your own uploads still work and take priority when switched on. The playmat motion options work on them too.'] },
  { v: '0.55.0', title: 'Suspend works', notes: ['Cards with Suspend (Rift Bolt, Ancestral Vision, Living End…) get a "Suspend N (cost)" item in their hand menu. It follows the rules: you can suspend any time you could begin to cast the card, you pay the suspend cost, and it is exiled with N time counters (shown in the Exile list).','At the start of each of your upkeeps a trigger removes a time counter. When the last one is removed a second trigger casts the card for free (you choose its modes and targets); creatures cast this way have haste. If it cannot be cast it stays in exile.'] },
  { v: '0.54.1', title: 'More realistic foil', notes: ['Foil now behaves like a real foil card: fine colour bands slide across the card as the light angle changes, a soft glare follows the mouse, tiny glints sparkle only near the light, and the big preview tilts toward your mouse. When you are not hovering, the light drifts slowly on its own.'] },
  { v: '0.54.0', title: 'Foil cards', notes: ['Settings → Foil cards: a holographic rainbow sheen with a little sparkle on every card, or on about one card in five. It slowly sweeps over the card and follows the mouse when you hover. Works on text tiles, card images and the big preview. Strength slider.'] },
  { v: '0.53.0', title: 'Custom mouse cursor', notes: ['Settings → Mouse cursor: gold arrow, magic wand, sword, or a glowing mana orb in any of the five colours, or your own image. Each has a brighter version over things you can click. Small / medium / large.'] },
  { v: '0.52.0', title: 'Moving playmat', notes: ['Settings → Playmat → Playmat motion: slow drift, gentle breathing, a passing light, or a picture that follows the mouse. Works on your custom image and on the colour themes. Only the picture moves, never the cards. There is a speed slider, and it respects the system "reduce motion" setting.'] },
  { v: '0.51.1', title: 'Softer sounds and background music', notes: ['The casting sound is now a soft low swell instead of a bright sweep.','All sound effects have a gentle room reverb.','New endless background music: a calm ambient loop of slow chords and soft bells, generated in the app. Settings → Sound has its own switch and volume. It starts after your first click.'] },
  { v: '0.51.0', title: 'Sound effects', notes: ['New sounds for drawing a card, casting a spell, a permanent entering the battlefield, playing a land, a spell or ability resolving, and a spell being countered. All are generated in the app (no audio files, works offline).','Settings → Sound: master switch, volume, and a switch for each sound.'] },
  { v: '0.50.0', title: 'Triggers are real stack objects', notes: ['Land "when this enters, surveil/scry N" triggers now go through the trigger window, sit on the stack (you can respond), and resolve from there, instead of popping up on their own.','Targets for a triggered ability are chosen when it goes on the stack, so it can fizzle if the target leaves.','The opponent box can now put a triggered/activated ability on the stack (type: triggered/activated ability), so you can counter or respond to it. Stack rows say Triggered ability vs Activated ability.'] },
  { v: '0.49.0', title: 'Effect durations and delayed effects', notes: ['One ledger now tracks everything that lasts: "until end of turn", "until your next turn", "while the source stays on the battlefield" and delayed triggers. Temporary pumps and keyword grants end in the cleanup step (or at your next turn), effects tied to a permanent end when it leaves, and the log says what ended.','The effect panel understands more: "gets +2/+2 until end of turn" and "gains flying/haste/lifelink… until end of turn" for yourself, a target or "creatures you control"; "at the beginning of the next end step, exile / sacrifice / return it" and "at your next upkeep, draw a card" become delayed triggers that actually fire; "exile target permanent until ~ leaves the battlefield" (Leyline Binding style) returns the card when the source leaves; any other "this turn" sentence can be kept as a timed reminder.','New Effects button (top of the table, only when something is active) lists every lasting effect with when it ends and lets you remove one. An hourglass badge marks creatures with a lasting effect, and the preview lists them. Temporary keywords also show as icons. Toggle: Effect timers.'] },
  { v: '0.48.0', title: 'Keyword icons', notes: ['Keywords a creature has right now because of another permanent or a condition (Scion of Draco, delirium…) are shown as small round icons on its tile instead of a text label: wings = flying, wizard hat = hexproof, sword = first strike, crossed swords = double strike, skull = deathtouch, lightning = haste, shield = indestructible, heart = lifelink, two figures = menace, arrow = reach, paw = trample, eye = vigilance, wall = defender. Hover an icon for its name and where it comes from.','The enlarged preview has a new "Active now" row listing every keyword the creature has at this moment (printed and granted; * = granted), and the keyword chips carry the same icons. Turn it off with the new teaching toggle "Active keyword icons".'] },
  { v: '0.47.3', title: 'One-click installer', notes: ['The Windows installer now installs in one click (no wizard), adds desktop and Start menu shortcuts and opens the game. Build-Installer.bat also produces a ready-to-share MTG-Playtester-Share.zip.'] },
  { v: '0.47.2', title: 'Delirium on real card data', notes: ['Fixed: static abilities were not read on cards whose name has a curly apostrophe (Dragon\u2019s Rage Channeler and similar), so the delirium bonus never applied with real Scryfall data. The P/T box now changes to 3/3 and flying turns on when you reach four card types.','Active keywords are now visible: a green keyword pill on the card (FLYING) while it is active, and in the preview the keyword chip shows a check mark when active and is dashed/dim when not.'] },
  { v: '0.47.1', title: 'Delirium badge', notes: ['The delirium counter now reads "\u0394 4/4" and sits above the power/toughness corner so it cannot be mistaken for a P/T. The card\u2019s own P/T box already shows the new stats (green 3/3 over the printed 1/1), the same way as Cosmogoyf.'] },
  { v: '0.47.0', title: 'Delirium', notes: ['Cards with Delirium now check the graveyard live. Dragon\u2019s Rage Channeler (and any "As long as there are four or more card types among cards in your graveyard, ~ gets +2/+2, has flying…" line) gets its bonus and keywords automatically when you reach four types, and loses them when you drop below.','A purple n/4 badge on every card that uses delirium (hand, battlefield, anywhere) shows how many card types are in your graveyard and glows gold when delirium is active. The card preview explains what is active. "Attacks each combat if able" is shown but not enforced.'] },
  { v: '0.46.0', title: 'The cost system', notes: ['One model for everything a spell or ability costs. Before paying, a window now lets you choose HOW to pay when there is a choice: the normal cost, an alternative cost (Evoke, "exile a blue card from your hand", "pay 1 life and exile…", "return an Island you control") or optional extras like Kicker.','Cost increases and reductions on the board are applied automatically and shown on the card in hand: Thalia and Sphere of Resistance style taxes, Goblin Electromancer style reductions, Affinity, plus the existing "costs {N} less for each…". Taxes also apply to alternative costs. Tools → Cost effects lets you add effects the app cannot see (an opponent\u2019s Thalia).','Non-mana costs are real choices now: "As an additional cost… sacrifice/discard/exile", abilities that say "Sacrifice a creature", "Discard a card", "Exile a card from your graveyard", "Tap an untapped creature you control", "Return a land you control to its owner\u2019s hand". A window asks which cards pay; nothing changes until every choice is made, and cancelling leaves the game untouched. Before, these were left for you to pay by hand.','Delve, Convoke and Improvise open a window where the cards you choose pay part of the mana cost. Cycling works from your hand (right-click \u2192 Cycle): the cost is paid, the card is discarded and "draw a card" goes on the stack. Evoked creatures queue their sacrifice trigger.','Hand outlines now count alternative and additional costs, so a card you can only cast by pitching glows, and the tooltip explains an unpayable additional cost. New teaching toggle: Cost explanations.'] },
  { v: '0.45.0', title: 'Targeting', notes: ['The app now reads "target …" from spells and abilities (any target, target creature you control, up to two target creatures, target player or opponent, target spell, target card in a graveyard, target nonland permanent…). When you cast the spell or activate the ability a window lists every legal target (your permanents, you, the opponent, spells on the stack, your graveyard) and you choose before paying. Things your opponent controls are offered as "not tracked here" so the cast can still go ahead.','When it resolves the targets are checked again: gone targets are skipped, and if every target is gone the spell or ability fizzles (a spell goes to the graveyard and does nothing). Triggered abilities and loyalty abilities ask for their targets as they resolve.','The effect buttons are now tied to the targets you chose: Deal 3 damage to Opponent, Destroy Grizzly Bears, Exile X, Return X to its owner\'s hand, Tap/Untap X, X gets +2/+2 until end of turn, Put a +1/+1 counter on X, Counter that spell, target player draws/gains/loses. Creatures now keep damage marked until end of turn and die to lethal damage (indestructible survives).','The stack window has an "Opponent casts it" box: add the spell your real opponent cast. You can counter it, respond to it, or target it with your own counterspell. Opponent spells resolve with a reminder to apply their effects by hand. The Stack button works even when the stack is empty.'] },
  { v: '0.44.0', title: 'One way onto and off the battlefield', notes: ['Everything that puts a permanent onto the battlefield (playing a land, a spell resolving, fetching, reanimating, making a token, dragging a card by hand, pre-game Leylines) now goes through one routine, and everything that removes one (dying, sacrifice, state-based actions, the legend rule, bouncing, exiling) goes through another. Tapped-or-untapped, the shockland question, surveil lands, enters-the-battlefield and landfall triggers, "exile it instead" and dies/leaves triggers are now handled in exactly one place, so they work the same whichever way a card moves.','Tokens now trigger "whenever a creature enters" abilities, and tokens that die trigger "whenever a creature dies".','The game now remembers what entered, left and died this turn, ready for cards that count them.'] },
  { v: '0.43.0', title: 'Card-pool coverage scan', notes: ['New: How the app reads cards… > Scan every card in the card data. It runs the card reader over every card and ranks the rules phrasings the app does not understand, most common first (also grouped by how the phrase starts, plus keywords it only explains). Copy or save the report to decide what to teach the app next.','Re-import the Oracle file once to enable the "Modern-legal cards only" filter.'] },
  { v: '0.42.0', title: 'Fetched lands, Goryo\'s Vengeance, Countered', notes: ['A fetched land now does everything it does when it enters: a shockland asks whether to pay 2 life, surveil lands surveil, and enters-tapped rules apply. Lands you drag onto the battlefield by hand do the same.','"Return target ... card from your graveyard to the battlefield / your hand" spells (Goryo\'s Vengeance, Reanimate, Raise Dead...): you choose the target when you cast the spell, before paying. On resolution the card is returned automatically. If the target left the graveyard the spell does nothing. Goryo\'s Vengeance also gives haste, exiles the creature at the next end step, and exiles it instead if it would leave the battlefield.','New Countered button on the stack: removes the top spell or ability without resolving it (a spell goes to the graveyard), for playtesting against another player.'] },
  { v: '0.41.1', title: 'Lifelink and big "draw N" numbers', notes: ['Lifelink now works in combat: the damage a lifelinker deals also gains you that much life (Griselbrand attacking = +7), it is logged, and "whenever you gain life" triggers fire.','Effects that use number words above five ("Draw seven cards", "create six tokens", "put ten counters"...) are now recognised up to ten; before, Griselbrand\'s "Pay 7 life: Draw seven cards" paid the life but the draw was not offered.'] },
  { v: '0.41.0', title: 'Surveil and scry done properly', notes: ['Surveil lands (Undercity Sewers, Meticulous Archive and the rest) enter tapped, then the surveil window opens for the "When this enters, surveil N" trigger and names the card that caused it.','The window shows the cards you looked at in two groups: those that stay on top (with up/down arrows so you choose the order, first = next draw) and those leaving (to the graveyard for surveil, to the bottom for scry). One click moves a card between groups.','If your library has fewer cards than N you look at all of them; with an empty library nothing opens. The window can no longer be cancelled by accident, and the log names every card put into the graveyard.'] },
  { v: '0.40.1', title: 'New top bar', notes: ['The top bar is regrouped: logo and deck picker on the left, New game + On the play together, the six game actions (Undo, Shuffle, Draw, Untap all, Token, Stack) as one icon-and-label button strip, then status chips (green dot = ready, amber = needs attention), the version, and Tools & Settings on the right.','On narrower windows the button labels hide and only icons show (hover for the name and shortcut). The version badge shows just the number; hover or click it for what changed.'] },
  { v: '0.40.0', title: 'Board frames + tidier pre-game screen', notes: ['New Settings \u2192 Board frame: Fire, Ice, Grass, Storm, Shadow and Royal gold put a glowing, slowly moving coloured outline around the playmat and tint the borders of the zones, hand and top bar. Pick Custom to choose your own two colours.','Animated glow can be switched off (still outline) and the glow strength has its own slider. Frames are independent of the playmat colour/image.','The Pre-game actions screen is laid out properly: each opening-hand card shows its name, what its ability does, and its button; the hint and Continue button have room to breathe.'] },
  { v: '0.39.3', title: 'Cast-time vs trigger "choose one"', notes: ['The app now tells apart where a "choose one" sits. On an instant or sorcery it is chosen as you cast the spell. After "When/Whenever/At the beginning of" (Territorial Kavu: "Whenever this creature attacks, choose one") it is a triggered ability and is chosen when the trigger goes on the stack \u2014 casting the creature no longer opens the mode window. A "choose one" after a cost and colon is chosen when you activate the ability.','The card reader says which kind each modal line is.'] },
  { v: '0.39.2', title: 'Auto-pay sees every colour a land can make', notes: ['Auto-payment, the hand outlines (Playable / Can\'t pay) and the mana window now use the same land-colour rules as tapping a land by hand: printed mana plus every basic land type the board gives it. With Leyline of the Guildpact in play every land can pay for any colour; Blood Moon-style effects reduce nonbasic lands to red.'] },
  { v: '0.39.1', title: 'P/T box text always fits', notes: ['The number inside the live P/T box now scales down with its length (3/4, 10/11, 12/13...) so it always stays inside the box, on the card and in the hover preview. Applies to every creature with changed or variable power/toughness.'] },
  { v: '0.39.0', title: 'Live power/toughness shown on the card', notes: ['When a creature\'s power/toughness differs from what is printed (Cosmogoyf, Territorial Kavu, counters, anthems, until-end-of-turn pumps), a P/T box now appears over the printed box on the card, even when card pictures are on.','Ring colour: green = bigger than printed, red = smaller, gold = changes with the game (a \u2605 value). The box flashes briefly whenever the number changes.','The large hover preview shows the same box over the picture; hover the box for the reasons (printed value and every effect).'] },
  { v: '0.38.0', title: 'Choose-one / choose-two (modal) cards', notes: ['The app now recognises "Choose one \u2014", "Choose two \u2014", "Choose one or both \u2014", "Choose one or more \u2014", "Choose up to N \u2014" and Spree. Casting such a card (Kolaghan\'s Command, Cryptic Command, charms...) opens a window listing every mode; you pick the right number before paying, and the window will not let you pick too many or too few.','Only the modes you chose resolve, in printed order. They show on the stack, and the effects panel offers just those (for example Kolaghan\'s Command: deal 2 damage). Modes the app cannot apply by itself are labelled "you apply this one by hand".','Works for spells, triggered abilities (the mode is chosen as the trigger goes on the stack, e.g. Territorial Kavu) and activated abilities. Spree extras add their cost to the spell and the window shows the total.','The card reader (How the app reads cards) shows each mode and whether the app applies it.'] },
  { v: '0.37.0', title: 'Cosmogoyf fixed, live power/toughness for any count', notes: ['Cosmogoyf now works: its real text counts the cards you own in exile (power = that number, toughness = that number + 1). The app did not recognise that wording before, which is why it showed 0/0 or a question mark.','Power/toughness that depends on a count is now read generically: cards in exile, creature/land/etc. cards in your graveyard, cards in hand/graveyard/library, your life total, and anything "you control" (Elves, other creatures, artifacts, legendary permanents...), with optional "plus N".','New: "until end of turn" power/toughness changes. Right-click a creature for +1/+1, +2/+2 or \u22121/\u22121 until end of turn; effects that say "this creature gets +X/+X until end of turn" (prowess) are offered when they resolve. They wear off at cleanup and show in the hover note.','Modal abilities such as Territorial Kavu\'s attack trigger now list each mode separately.'] },
  { v: '0.36.0', title: 'One effect list, more abilities and triggers', notes: ['The card reader and the game now share one list of effects, so what "How the app reads cards" reports is exactly what the game does. New effects: opponent damage and life loss (Ballista pings, Bolt-style spells), +N counters, create tokens (e.g. two 1/1 Soldiers), Add mana (rituals like Dark Ritual), mill.','Cards with several activated abilities (Walking Ballista) now offer each one. Costs are paid for you: mana through the payment window, {T}, sacrificing itself, removing counters, paying life. Costs the app cannot pay are listed for you to pay by hand. Instants and sorceries now open the suggested-effects panel whenever the app recognises an effect.','New trigger events: when this leaves the battlefield, whenever you gain life, whenever this (or a creature you control) deals combat damage to a player.'] },
  { v: '0.35.0', title: 'The app reads cards: card model and timing rules', notes: ['New: Tools & Settings > "How the app reads cards" (and right-click any card > "How the app reads this card"). Every rules line is classified as keyword, mana, activated, triggered, static, loyalty or spell effect and marked Understood, Partly or Not understood, with a coverage summary for your whole deck.','Activation restrictions are now read from the card text and checked: as a sorcery, during your upkeep / draw step / end step / combat / before blockers, once each turn, if you control a (type), if you have no cards in hand, N or more cards in your graveyard. They apply to mana abilities and other activated abilities, and the green outline respects them.','Static abilities are listed per line using the v0.34 engine.'] },
  { v: '0.34.0', title: 'Static abilities apply to everything', notes: ['New static-ability engine: every permanent\'s rules text is read and each effect is applied to ALL permanents it describes, not just the cards tested so far. Covers "is all colors / is red / is colorless", "Each creature you control has vigilance if it\'s white...", and "Other Dragons you control get +1/+1" style power/toughness boosts, for subjects like each/other/all, colours, nonland, legendary, creature types (changeling counts) and more.','Leyline of the Guildpact now makes every nonland permanent all five colours everywhere: the card colour, Scion of Draco\'s grants, colour conditions and the preview note all agree.','Hand key simplified to Playable / Can\'t pay (not enough mana or wrong colours) / Wrong timing, with the exact reason on hover.'] },
  { v: '0.33.0', title: 'Hand reordering and a clearer key', notes: ['Drag cards sideways in your hand to reorder them; a gold line shows where the card will land. A Sort menu offers lands first, mana value, colour and playable first.','Outline key rebuilt: green = playable, red = not enough mana, purple = enough mana but wrong colours, gold = not now (hover for the exact reason: wrong phase, busy stack, land already played), white = selected. The lightning badge means instant speed.'] },
  { v: '0.32.0', title: 'Library menu and tidier piles', notes: ['Click (or right-click) the library to open a menu: Draw, Look at top N, Scry N, Surveil N, Mill N, Search, Shuffle. The always-visible buttons are gone, and clicking no longer draws by accident.','Library, graveyard and exile are redrawn as piles with a count badge; the library gets thicker or thinner with its size.','New teaching switch: Library menu tip (hover tip on the library).'] },
  { v: '0.31.0', title: 'X spells', notes: ['Spells with {X} in the cost now ask you to choose X when you cast them, showing the largest X your mana allows and the total cost. Two {X} symbols (Walking Ballista) cost two mana per point of X.', 'X is remembered on the stack (shown as X = n). Permanents that enter with X +1/+1 counters get them; enter-the-battlefield abilities use your X; instants and sorceries offer suggested effects with X filled in (e.g. Draw 3 cards).', 'Limits: activated abilities with {X} in their cost are not handled yet, and counter types other than +1/+1 are left for you to add by hand.'] },
  { v: '0.30.0', title: 'Live power and toughness', notes: ['Creatures show their real power/toughness: Territorial Kavu (basic land types), Cosmogoyf/Tarmogoyf (card types in graveyards, toughness +1), other "equal to the number of..." creatures, +1/+1 and -1/-1 counters, and anthems.', 'Hover a changed creature to see why it is that size.', 'A creature with toughness 0 or less dies (state-based action), e.g. Kavu with no basic lands.', 'Goldfish combat damage uses the live numbers.'] },
  { v: '0.29.1', title: 'Closing a pop-up no longer breaks the game', notes: ['Closing (✕ or Esc) a shock land pop-up now cancels the whole land play: nothing is paid and the land returns to your hand. A Cancel button says the same.', 'Pop-ups that must be answered (triggered abilities, ability resolution, legend rule, cascade, scry/surveil) no longer have a ✕ and ignore Esc, so a decision cannot be skipped by accident.', 'Scion of Draco keyword list corrected: vigilance, hexproof, lifelink, first strike and trample (no haste or deathtouch).'] },
  { v: '0.29.0', title: 'Static abilities work together', notes: ['Static keyword grants now follow current colours: with Leyline of the Guildpact, Scion of Draco gives every creature vigilance, hexproof, lifelink, first strike and trample (it grants no haste, so summoning sickness is unchanged). Any granted haste would remove summoning sickness.', 'The card preview lists keywords and colours a card gets from other permanents.', 'Fetch lands: the Activate ability menu item and double-click now run the fetch instead of only showing its text.', 'Version badge and this What\'s new list at the top right.'] },
  { v: '0.28.0', title: 'Summoning sickness and combat', notes: ['Summoning sickness glow and enforcement, attack declaration with reasons, vigilance, defender, goldfish combat damage and opponent life, flash read from keyword lines.'] },
  { v: '0.27.0', title: 'Activated ability outlines', notes: ['Green outline on permanents whose activated ability can be used now.'] },
  { v: '0.26.1', title: 'Fetch land fixes', notes: ['Library lands keep printed types (Leyline no longer widens fetches); tapped fetches cannot be cracked; Expanse and Fabled Passage details.'] },
  { v: '0.26.0', title: 'Legend rule and mana rocks', notes: ['Legend rule prompt, general mana rocks (Sol Ring, Moxen), soft static-ability checks.'] },
  { v: '0.25.0', title: '{0} spells and Mishra\'s Bauble', notes: ['Zero-cost spells castable; activated abilities with sacrifice costs, targets, and delayed draws.'] },
  { v: '0.24.0', title: 'Visual deck view', notes: ['Deck stats as stacks of card images, curve and colour header, card-data status fix.'] },
  { v: '0.23.0', title: 'Triggers, Necrodominance, planeswalkers', notes: ['Triggered ability engine, Necrodominance static effects, planeswalker loyalty, deck stats overview.'] },
  { v: '0.22.0', title: 'Teaching switches', notes: ['Every teaching aid is its own switch; Now/Next phase window; in-app updater.'] }
];
function openChangelog() {
  const m = modal(`What's new — you are running v${APP_VERSION}`, { width: 620 });
  for (const e of CHANGELOG) m.body.append(h('div', { class: 'clog' }, h('div', { class: 'clog-h' }, h('b', { text: 'v' + e.v }), ' ', h('span', { text: e.title })), h('ul', null, ...e.notes.map(n => h('li', { text: n })))));
  m.foot.append(h('button', { class: 'primary', text: 'Close', onclick: () => m.close() }));
}
function setupVersionBadge() {
  const b = $('#btnVersion'); if (!b) return;
  const top = CHANGELOG[0];
  b.textContent = `v${APP_VERSION}`;
  b.title = `You are running version ${APP_VERSION} — ${top.title}. Click to see what changed.`;
  b.addEventListener('click', openChangelog);
}

// v0.94.0 Update window: shows on start when a newer version is on GitHub, installs it with a progress bar, then offers a restart.
const RELEASES_URL = 'https://github.com/snipeuoutjsl-netizen/MTG-Playtester/releases/latest';
const fmtMB = n => (n / 1048576).toFixed(n >= 10485760 ? 0 : 1) + ' MB';
function makeProgress() {
  const fill = h('div', { class: 'upd-fill' }), bar = h('div', { class: 'upd-bar', role: 'progressbar', 'aria-valuemin': '0', 'aria-valuemax': '100' }, fill), txt = h('div', { class: 'small muted upd-txt', text: '' });
  return { el: h('div', { class: 'upd-prog' }, bar, txt), set(pct, t) { bar.classList.remove('indet'); fill.style.width = Math.max(0, Math.min(100, pct)) + '%'; bar.setAttribute('aria-valuenow', String(Math.round(pct))); txt.textContent = t || ''; }, indet(t) { bar.classList.add('indet'); txt.textContent = t || ''; } };
}
// Runs the GitHub install and drives a progress bar; resolves with the result of ghInstall.
async function installWithProgress(prog, bytesHint) {
  prog.indet('Starting\u2026');
  let off = null;
  if (window.desktop && typeof window.desktop.onProgress === 'function') off = window.desktop.onProgress(d => {
    if (d.phase === 'download') { const tot = d.total || bytesHint || 0; if (tot) prog.set((d.done / tot) * 92, `Downloading ${d.file} \u2014 ${fmtMB(d.done)} of ${fmtMB(tot)}`); else prog.indet(`Downloading ${d.file}\u2026`); }
    else if (d.phase === 'verify') prog.set((d.done / (d.total || bytesHint || d.done || 1)) * 92, `Checking ${d.file} against its published fingerprint\u2026`);
    else if (d.phase === 'install') prog.set(96, 'Installing\u2026');
    else if (d.phase === 'done') prog.set(100, 'Done');
  }); else prog.indet('Downloading and checking files\u2026');
  try { const r = await window.desktop.ghInstall(); if (r && r.ok && !r.upToDate) prog.set(100, 'Installed and verified'); return r; }
  finally { if (off) off(); }
}
// v0.94.7 ONE update window. The start-up notice and ⚙ → Update app are the same window: `openUpdate(pre)` shows a result that was already fetched
// (start-up) or checks GitHub itself (menu). Folder / web-address updates and "back to built-in" live under "Other ways to update".
async function openUpdate(pre) {
  if (!window.desktop) return;
  const m = modal('Update app', { width: 560, sticky: !!pre });
  const info = await window.desktop.info();
  const body = h('div'), prog = makeProgress(), status = h('p', { class: 'small', style: 'color:var(--gold)' }), note = h('p', { class: 'small', style: 'color:var(--gold)' });
  prog.el.hidden = true;
  const restartBtn = h('button', { class: 'primary', text: 'Restart now', hidden: true, onclick: () => window.desktop.restart() });
  const later = h('button', { text: 'Close', onclick: () => m.close() });
  const skip = h('button', { text: 'Skip this version', hidden: true });
  const go = h('button', { class: 'primary', text: 'Update now', hidden: true });
  const again = h('button', { text: 'Check again' });
  let cur = null, restartNow = false;
  const afterInstall = (v) => { status.textContent = `Version ${v} is installed and verified.` + (state ? ' Restarting ends the game in progress, so restart whenever you like.' : ''); go.hidden = true; skip.hidden = true; restartBtn.hidden = false; later.textContent = 'Restart later'; restartNow = true; };
  const show = r => {
    body.replaceChildren(); status.textContent = ''; go.hidden = skip.hidden = true; go.disabled = later.disabled = skip.disabled = false;
    if (!r || !r.ok) { body.append(h('p', null, 'Could not check GitHub: ' + ((r && r.error) || 'no answer') + '. You can still update from a folder below.')); return; }
    if (r.none) { body.append(h('p', null, 'No usable release was found on GitHub. The newest release must be published (not a draft or pre-release) and must include latest.json.')); return; }
    if (!r.newer) { body.append(h('p', null, 'You have the newest version (', h('b', { text: r.current }), ').')); return; }
    cur = r;
    body.append(h('p', null, `You have version ${r.current}. Version `, h('b', { text: r.latest }), ' is ready on GitHub', r.bytes ? ` (${fmtMB(r.bytes)}).` : '.'), r.title ? h('div', { class: 'ptitle', text: r.title }) : null, r.notes && r.notes.length ? h('ul', { class: 'small upd-notes' }, ...r.notes.map(n => h('li', { text: n }))) : null);
    if (r.needsInstaller) { status.textContent = 'This release also changes the app shell, so it cannot be installed from inside the app. Download the full package from the release page and run Build-Installer.bat once.'; go.textContent = 'Open release page'; go.hidden = false; go.onclick = () => window.open(RELEASES_URL, '_blank'); return; }
    go.textContent = 'Update now'; go.hidden = false; skip.hidden = false;
    go.onclick = async () => {
      go.disabled = later.disabled = skip.disabled = true; prog.el.hidden = false; status.textContent = '';
      const res = await installWithProgress(prog, r.bytes);
      if (!res || !res.ok) { prog.el.hidden = true; status.textContent = 'Update failed: ' + ((res && res.error) || 'unknown error') + ' Nothing was changed.'; go.textContent = 'Try again'; go.disabled = later.disabled = skip.disabled = false; return; }
      afterInstall(res.version);
    };
    skip.onclick = () => { settings.skipUpdate = r.latest; saveSettings(); m.close(); };
  };
  const check = async () => {
    if (!window.desktop.ghCheck) { body.replaceChildren(h('p', null, 'This app shell is older and cannot check GitHub. Install the full package once (run Build-Installer.bat), or update from a folder below.')); return; }
    body.replaceChildren(h('p', { class: 'muted', text: 'Checking GitHub…' })); again.disabled = true;
    try { show(await window.desktop.ghCheck()); } finally { again.disabled = false; }
  };
  again.addEventListener('click', check);
  const report = r => {
    if (!r || r.cancelled) return;
    if (!r.ok) { note.textContent = 'Update failed: ' + r.error; return; }
    if (r.upToDate) { note.textContent = `You already have the newest version (${r.version}).`; return; }
    note.textContent = `Version ${r.version} is ready.` + (r.olderOrSame ? ' It is not newer than the built-in version, so the built-in one will keep running.' : ' Restart the app to use it.') + (r.needsInstaller ? ' Note: this release also changes the app shell, so run Build-Installer.bat once to get that part.' : '');
    if (!r.olderOrSame) { restartBtn.hidden = false; }
  };
  const url = h('input', { type: 'text', placeholder: 'https://example.com/mtg-playtester', value: lsGet('mtgpt.updateUrl', '') });
  const opt = (label, key, dflt) => { const c = h('input', { type: 'checkbox' }); c.checked = settings[key] !== false; c.addEventListener('change', () => { settings[key] = c.checked; saveSettings(); }); return h('label', { class: 'small', style: 'display:block;margin:6px 0' }, c, ' ' + label); };
  const other = h('details', { class: 'upd-other' }, h('summary', { text: 'Other ways to update' }),
    h('div', { class: 'fhead', text: 'From a folder' }),
    h('p', { class: 'small muted', text: 'Extract a new zip anywhere, then choose the folder that contains index.html. Your decks, card data and settings are kept.' }),
    h('button', { text: 'Update from folder…', onclick: async () => { note.textContent = 'Working…'; report(await window.desktop.fromFolder()); if (note.textContent === 'Working…') note.textContent = ''; } }),
    h('div', { class: 'fhead', text: 'From a web address' }),
    h('p', { class: 'small muted', text: 'Put index.html, app.js, style.css and an update.json ({"version":"0.22.0"}) at one https address. This downloads and installs straight away.' }),
    url, h('div', { style: 'margin-top:6px' }, h('button', { text: 'Download & install from this address', onclick: async () => { if (!url.value.trim()) { note.textContent = 'Type an address first.'; return; } if (!window.confirm('This downloads the files from that address and installs them now (you restart the app afterwards to use them). Continue?')) return; lsSet('mtgpt.updateUrl', url.value); note.textContent = 'Downloading…'; report(await window.desktop.fromUrl(url.value)); } })),
    h('div', { class: 'fhead', text: 'Built-in version' }),
    h('button', { class: 'danger', text: 'Go back to built-in version', onclick: async () => { await window.desktop.reset(); note.textContent = 'Downloaded update removed. Restart to use the built-in version.'; restartBtn.hidden = false; } }));
  m.body.append(
    h('p', { class: 'small muted' }, 'Running version ', h('b', { text: String(info.running) }), ` (${info.source}). Built-in: ${info.bundled}${info.override ? ', downloaded update: ' + info.override : ''}.`),
    body, prog.el, status, note,
    opt('Check for updates when the app starts', 'autoUpdateCheck'),
    opt('Open this window when an update is found (otherwise only a small notice)', 'updatePrompt'),
    other);
  m.foot.append(again, skip, later, go, restartBtn);
  if (pre) show(pre); else check();
}
const openUpdatePrompt = r => openUpdate(r);   // the start-up notice is the same window

function openCardData() {
  const m = modal('Card data', { width: 560 });
  m.body.append(
    h('p', { text: cardCount ? `Loaded: ${cardCount.toLocaleString()} cards. Loading a new file replaces them.` : 'No card data loaded yet.' }),
    h('p', { class: 'small ' + (TOKENDB.size ? 'muted' : ''), style: TOKENDB.size ? '' : 'color:var(--gold)', text: TOKENDB.size ? `Token data: ${[...TOKENDB.values()].reduce((a, x) => a + x.length, 0)} official tokens (their real rules text is used when a card creates one).` : (cardCount ? 'Token data: none yet. Load the card file again once (or use the download button) so tokens get their real rules text.' : '') }),
    h('p', null, 'Two public sources work: Scryfall’s “Oracle Cards” (',
      h('b', { text: 'scryfall.com/docs/api/bulk-data' }),
      ') or the MTGJSON project’s “AtomicCards” (',
      h('b', { text: 'mtgjson.com/downloads/all-files' }),
      '). Download either file once in your web browser, then choose it below. It stays on this computer; nothing is uploaded and no internet is needed afterwards.'),
    h('p', { class: 'muted small', text: 'Parsing a big file can take 10–30 seconds and uses a few hundred MB of memory while it loads.' })
  );
  const note = h('p', { class: 'small', style: 'color:var(--gold)' });
  m.body.prepend(h('p', null, h('b', { text: 'Easiest: ' }), 'let the app download it (about 150 MB, once). It tries Scryfall first and switches to MTGJSON by itself if Scryfall cannot be reached.'));
  m.body.append(note);
  const dlBtn = h('button', { class: 'primary', text: cardCount ? 'Update card data' : 'Download card data' });
  dlBtn.addEventListener('click', async () => {
    dlBtn.disabled = true;
    const ok = await runBulkDownload(t => { note.textContent = t; });
    if (ok) m.close(); else dlBtn.disabled = false;
  });
  const mjBtn = h('button', { text: 'Use MTGJSON only', title: 'Skip Scryfall and download from the MTGJSON project', onclick: async () => { mjBtn.disabled = dlBtn.disabled = true; try { const blob = await downloadMtgjson(t => { note.textContent = t; updateDbStatus(t); }); await importCardData(blob); m.close(); } catch (e) { updateDbStatus(); note.textContent = 'MTGJSON did not work: ' + (e.reason || e.message) + ' Download “AtomicCards” in your web browser and use “Choose file…”.'; mjBtn.disabled = dlBtn.disabled = false; } } });
  m.foot.append(
    h('button', { text: 'Close', onclick: () => m.close() }), mjBtn, dlBtn,
    h('button', { text: 'Choose file…', onclick: () => { m.close(); $('#fileCards').click(); } })
  );
}

